// Generated by tools/voice.py from tools/build-script.js. Do not edit by hand.
window.NARRATION = {"intro": {"src": "audio/intro.mp3", "dur": 22.239, "cues": [{"t": 0.35, "d": 11.285, "kind": "line", "sub": "Between 1095 and 1192, tens of thousands of men and women from Western Europe sewed a cloth cross to their clothes and set out for Jerusalem."}, {"t": 12.055, "d": 4.245, "kind": "line", "sub": "Knights and peasants, bishops and kings. Most never came home."}, {"t": 16.721, "d": 5.099, "kind": "line", "sub": "This is their story, told as the Christian chroniclers of the time told it."}]}, "ch:first:clermont": {"src": "audio/ch-first-clermont.mp3", "dur": 73.889, "cues": [{"t": 0.35, "d": 4.373, "kind": "title", "sub": "27 November 1095. Deus vult!"}, {"t": 5.623, "d": 8.299, "kind": "line", "sub": "At the end of a council in central France, Urban preached in a field outside Clermont, because no church could hold the crowd."}, {"t": 14.342, "d": 5.312, "kind": "line", "sub": "He spoke of Eastern Christians suffering and of Jerusalem in foreign hands."}, {"t": 20.074, "d": 7.36, "kind": "line", "sub": "He told knights who spent their lives fighting each other to take up a different kind of warfare: an armed pilgrimage."}, {"t": 27.854, "d": 3.307, "kind": "line", "sub": "The crowd answered with one cry: God wills it!"}, {"t": 31.581, "d": 3.947, "kind": "line", "sub": "Bishop Adhemar of Le Puy knelt first to take the cross."}, {"t": 35.947, "d": 8.704, "kind": "line", "sub": "People cut cloth into crosses and sewed them onto their shoulders, taking literally Christ's words to take up the cross and follow him."}, {"t": 45.071, "d": 5.376, "kind": "line", "sub": "The council decreed that the journey would count in place of all penance for sin."}, {"t": 51.217, "d": 11.477, "kind": "quote", "sub": "Let those who have formerly been accustomed to contend wickedly in private warfare against the faithful now fight against the infidels. Let those who for a long time have been robbers now become knights.", "source": "Fulcher of Chartres, who was probably present"}, {"t": 63.795, "d": 9.344, "kind": "quote", "sub": "Whoever goes to Jerusalem to free the Church of God, out of devotion alone and not to gain honour or money, may count that journey in place of all penance.", "source": "Decree of the Council of Clermont"}]}, "part:first": {"src": "audio/part-first.mp3", "dur": 15.857, "cues": [{"t": 0.35, "d": 4.693, "kind": "title", "sub": "Part One. The First Crusade. 1095–1099."}, {"t": 5.943, "d": 9.493, "kind": "line", "sub": "Answering a plea from Byzantium, armies of knights and pilgrims cross Europe and Anatolia and take Jerusalem in 1099."}]}, "ch:first:prologue": {"src": "audio/ch-first-prologue.mp3", "dur": 65.083, "cues": [{"t": 0.35, "d": 4.779, "kind": "title", "sub": "1009–1094. A Christian East under threat."}, {"t": 6.029, "d": 2.88, "kind": "line", "sub": "Christianity was born in the East."}, {"t": 9.329, "d": 6.869, "kind": "line", "sub": "For a thousand years, believers had lived and worshipped across Syria, Anatolia and the Holy Land."}, {"t": 16.618, "d": 12.544, "kind": "line", "sub": "Jerusalem had been under Muslim rule since 638, but Western pilgrims still made the long journey to the Church of the Holy Sepulchre, built over the tomb of Christ."}, {"t": 29.582, "d": 8.235, "kind": "line", "sub": "In 1009 the Fatimid caliph al-Hakim had the Holy Sepulchre destroyed, and it was only partly rebuilt."}, {"t": 38.237, "d": 8.725, "kind": "line", "sub": "Then in 1071 the Seljuk Turks crushed the Byzantine army at Manzikert and captured Emperor Romanos IV."}, {"t": 47.382, "d": 3.499, "kind": "line", "sub": "Within a decade most of Anatolia was lost."}, {"t": 51.301, "d": 6.571, "kind": "line", "sub": "Nicaea, where the Nicene Creed was written in 325, became a Turkish capital."}, {"t": 58.291, "d": 3.627, "kind": "line", "sub": "Pilgrims coming home told of a dangerous road."}, {"t": 62.338, "d": 2.325, "kind": "line", "sub": "The Christian East was shrinking."}]}, "ch:first:piacenza": {"src": "audio/ch-first-piacenza.mp3", "dur": 49.826, "cues": [{"t": 0.35, "d": 3.861, "kind": "title", "sub": "March 1095. A plea from Constantinople."}, {"t": 5.111, "d": 7.339, "kind": "line", "sub": "Emperor Alexios I Komnenos had spent fourteen years holding the Byzantine Empire together."}, {"t": 12.87, "d": 10.347, "kind": "line", "sub": "In March 1095 his envoys reached a church council at Piacenza and asked Pope Urban II for Western knights to help fight the Turks."}, {"t": 23.637, "d": 3.072, "kind": "line", "sub": "Urban saw more than a military alliance."}, {"t": 27.129, "d": 5.184, "kind": "line", "sub": "The Great Schism of 1054 had split the Latin and Greek churches."}, {"t": 32.733, "d": 4.288, "kind": "line", "sub": "Coming to the aid of Eastern Christians might help heal that wound."}, {"t": 37.791, "d": 11.285, "kind": "quote", "sub": "An embassy of the emperor of Constantinople came to this synod and humbly begged the lord pope and all the faithful of Christ to bring some help against the pagans for the defence of the holy Church.", "source": "Bernold of Constance, Chronicle"}]}, "ch:first:peoples-crusade": {"src": "audio/ch-first-peoples-crusade.mp3", "dur": 57.147, "cues": [{"t": 0.35, "d": 4.053, "kind": "title", "sub": "April–August 1096. The People's Crusade."}, {"t": 5.303, "d": 6.08, "kind": "line", "sub": "Urban set the departure for 15 August 1096, but many would not wait."}, {"t": 11.803, "d": 6.528, "kind": "line", "sub": "Peter the Hermit gathered tens of thousands of commoners, along with some knights, women and children."}, {"t": 18.751, "d": 3.52, "kind": "line", "sub": "They left Cologne at Easter and walked down the Danube."}, {"t": 22.691, "d": 1.877, "kind": "line", "sub": "The march was disorderly."}, {"t": 24.989, "d": 4.757, "kind": "line", "sub": "Fights over food broke out in Hungary, at Belgrade and at Niš."}, {"t": 30.166, "d": 7.872, "kind": "line", "sub": "Other bands, led by Count Emicho, turned on the Jewish communities of the Rhineland at Speyer, Worms and Mainz."}, {"t": 38.458, "d": 3.819, "kind": "line", "sub": "Some bishops sheltered the Jews in their own palaces."}, {"t": 42.697, "d": 9.323, "kind": "line", "sub": "Christian chroniclers such as Albert of Aachen condemned the killings and saw the bands' later destruction in Hungary as God's judgment."}, {"t": 52.439, "d": 4.288, "kind": "line", "sub": "Peter's column reached Constantinople on 1 August."}]}, "ch:first:civetot": {"src": "audio/ch-first-civetot.mp3", "dur": 41.943, "cues": [{"t": 0.35, "d": 5.227, "kind": "title", "sub": "21 October 1096. Disaster at Civetot."}, {"t": 6.477, "d": 6.443, "kind": "line", "sub": "Alexios ferried Peter's followers across the Bosporus and told them to wait for the princes."}, {"t": 13.339, "d": 1.173, "kind": "line", "sub": "They did not."}, {"t": 14.933, "d": 2.709, "kind": "line", "sub": "Raiding parties pushed toward Nicaea."}, {"t": 18.062, "d": 9.728, "kind": "line", "sub": "In October, while Peter was in Constantinople seeking supplies, the army marched out and walked into an ambush by Sultan Kilij Arslan."}, {"t": 28.21, "d": 2.603, "kind": "line", "sub": "Most were killed or enslaved."}, {"t": 31.233, "d": 3.733, "kind": "line", "sub": "Byzantine ships rescued a few thousand survivors."}, {"t": 35.386, "d": 1.451, "kind": "line", "sub": "Peter survived."}, {"t": 37.257, "d": 4.267, "kind": "line", "sub": "He would march with the main army all the way to Jerusalem."}]}, "ch:first:princes": {"src": "audio/ch-first-princes.mp3", "dur": 54.858, "cues": [{"t": 0.35, "d": 4.736, "kind": "title", "sub": "August 1096 – May 1097. The princes march."}, {"t": 5.986, "d": 3.669, "kind": "line", "sub": "The main army set out on Urban's appointed day."}, {"t": 10.075, "d": 1.408, "kind": "line", "sub": "No king went."}, {"t": 11.903, "d": 3.648, "kind": "line", "sub": "It was led by great lords, each with his own following."}, {"t": 15.971, "d": 3.669, "kind": "line", "sub": "Godfrey of Bouillon marched overland through Hungary."}, {"t": 20.061, "d": 6.208, "kind": "line", "sub": "Raymond of Toulouse, with Bishop Adhemar, took the hard winter road down the Dalmatian coast."}, {"t": 26.689, "d": 4.139, "kind": "line", "sub": "Bohemond sailed from southern Italy across the Adriatic."}, {"t": 31.247, "d": 7.381, "kind": "line", "sub": "Hugh of Vermandois, Robert of Normandy, Robert of Flanders and Stephen of Blois led other contingents."}, {"t": 39.049, "d": 7.339, "kind": "line", "sub": "Historians estimate 60,000 to 100,000 people in all, perhaps 7,000 of them knights."}, {"t": 46.807, "d": 1.877, "kind": "line", "sub": "Most paid their own way."}, {"t": 49.105, "d": 5.333, "kind": "line", "sub": "Crusading cost a fortune, and many sold or mortgaged their land to go."}]}, "ch:first:constantinople": {"src": "audio/ch-first-constantinople.mp3", "dur": 47.249, "cues": [{"t": 0.35, "d": 5.376, "kind": "title", "sub": "December 1096 – April 1097. The emperor's oath."}, {"t": 6.626, "d": 8.256, "kind": "line", "sub": "Constantinople was the greatest Christian city in the world, with ten times the population of any city in the West."}, {"t": 15.302, "d": 4.053, "kind": "line", "sub": "Its walls, churches and relics left the Westerners in awe."}, {"t": 19.775, "d": 3.221, "kind": "line", "sub": "Alexios needed the princes on his side."}, {"t": 23.417, "d": 4.992, "kind": "line", "sub": "He asked each to swear to hand back any former Byzantine land they took."}, {"t": 28.829, "d": 1.152, "kind": "line", "sub": "Most swore."}, {"t": 30.401, "d": 4.459, "kind": "line", "sub": "Raymond would only promise to respect the emperor's life and honour."}, {"t": 35.279, "d": 3.499, "kind": "line", "sub": "Tancred slipped across to Asia rather than swear."}, {"t": 39.198, "d": 3.989, "kind": "line", "sub": "In return, Alexios promised food, guides and troops."}, {"t": 43.607, "d": 3.221, "kind": "line", "sub": "By spring the army was across the Bosporus."}]}, "ch:first:nicaea": {"src": "audio/ch-first-nicaea.mp3", "dur": 47.838, "cues": [{"t": 0.35, "d": 6.08, "kind": "title", "sub": "14 May – 19 June 1097. The siege of Nicaea."}, {"t": 7.33, "d": 8.0, "kind": "line", "sub": "The first target was Nicaea, the city of the first great council of the Church and now the Turkish sultan's capital."}, {"t": 15.75, "d": 3.499, "kind": "line", "sub": "Kilij Arslan was away fighting in the east."}, {"t": 19.669, "d": 3.989, "kind": "line", "sub": "He hurried back on 21 May and was driven off."}, {"t": 24.078, "d": 7.467, "kind": "line", "sub": "The city's west side opened onto a lake, so the Byzantines hauled boats overland and launched them to cut it off."}, {"t": 31.965, "d": 5.845, "kind": "line", "sub": "On 19 June the garrison surrendered to Alexios, not to the crusaders."}, {"t": 38.23, "d": 2.88, "kind": "line", "sub": "Imperial banners went up on the walls."}, {"t": 41.53, "d": 5.888, "kind": "line", "sub": "Many crusaders felt robbed of plunder, but the emperor rewarded the leaders generously."}]}, "ch:first:dorylaeum": {"src": "audio/ch-first-dorylaeum.mp3", "dur": 46.762, "cues": [{"t": 0.35, "d": 4.757, "kind": "title", "sub": "1 July 1097. The battle of Dorylaeum."}, {"t": 6.007, "d": 3.285, "kind": "line", "sub": "To ease supply the army marched in two groups."}, {"t": 9.713, "d": 5.419, "kind": "line", "sub": "Near Dorylaeum, Turkish horse archers surrounded the vanguard under Bohemond."}, {"t": 15.551, "d": 5.696, "kind": "line", "sub": "The Christians pulled into a tight camp and held out for hours under a storm of arrows."}, {"t": 21.667, "d": 3.008, "kind": "line", "sub": "Women carried water to the fighting men."}, {"t": 25.095, "d": 7.616, "kind": "line", "sub": "Then Godfrey and Raymond arrived with the second army, and Bishop Adhemar's troops came over the hills behind the Turks."}, {"t": 33.131, "d": 3.008, "kind": "line", "sub": "The sultan fled and left his camp behind."}, {"t": 36.559, "d": 3.093, "kind": "line", "sub": "The road across Anatolia was open."}, {"t": 40.423, "d": 5.589, "kind": "quote", "sub": "Stand fast all together, trusting in Christ and in the victory of the Holy Cross.", "source": "Gesta Francorum, the word passed along the line"}]}, "ch:first:anatolia": {"src": "audio/ch-first-anatolia.mp3", "dur": 45.065, "cues": [{"t": 0.35, "d": 4.544, "kind": "title", "sub": "July – October 1097. Across Anatolia."}, {"t": 5.794, "d": 3.797, "kind": "line", "sub": "The summer march across the dry interior was brutal."}, {"t": 10.011, "d": 2.581, "kind": "line", "sub": "Men and horses died of thirst."}, {"t": 13.013, "d": 7.04, "kind": "line", "sub": "Knights rode oxen, and the anonymous author of the Gesta says goats, sheep and dogs carried the baggage."}, {"t": 20.473, "d": 6.741, "kind": "line", "sub": "After Heraclea, Tancred and Baldwin of Boulogne turned south through the Cilician Gates to Tarsus."}, {"t": 27.634, "d": 8.939, "kind": "line", "sub": "The main army took the longer road north through Caesarea and over the Anti-Taurus mountains, where Armenian Christians welcomed them."}, {"t": 36.993, "d": 3.2, "kind": "line", "sub": "At Marash, Baldwin's wife Godehilde died."}, {"t": 40.613, "d": 4.032, "kind": "line", "sub": "Soon after, he rode east with a small company of knights."}]}, "ch:first:antioch-siege": {"src": "audio/ch-first-antioch-siege.mp3", "dur": 43.763, "cues": [{"t": 0.35, "d": 5.376, "kind": "title", "sub": "21 October 1097. Before the walls of Antioch."}, {"t": 6.626, "d": 3.605, "kind": "line", "sub": "Antioch was one of the oldest centres of the faith."}, {"t": 10.651, "d": 9.109, "kind": "line", "sub": "By tradition St Peter led the church there, and it was where believers were first called Christians (Acts 11:26)."}, {"t": 20.181, "d": 5.653, "kind": "line", "sub": "Its walls ran for miles, with some 400 towers climbing up the mountainside."}, {"t": 26.254, "d": 2.56, "kind": "line", "sub": "The crusaders could not surround it."}, {"t": 29.234, "d": 4.053, "kind": "line", "sub": "The siege lasted almost eight months through a hard winter."}, {"t": 33.707, "d": 4.992, "kind": "line", "sub": "Famine set in, foraging parties were ambushed, and some men deserted."}, {"t": 39.119, "d": 4.224, "kind": "line", "sub": "Two relief armies from Damascus and Aleppo were beaten off."}]}, "ch:first:edessa": {"src": "audio/ch-first-edessa.mp3", "dur": 40.115, "cues": [{"t": 0.35, "d": 4.352, "kind": "title", "sub": "10 March 1098. The first crusader state."}, {"t": 5.602, "d": 6.187, "kind": "line", "sub": "Baldwin reached Edessa, an Armenian Christian city ruled by a lord named Thoros."}, {"t": 12.209, "d": 3.52, "kind": "line", "sub": "Thoros adopted Baldwin as his son and heir."}, {"t": 16.149, "d": 4.736, "kind": "line", "sub": "Weeks later a revolt overthrew Thoros, and the crowd killed him."}, {"t": 21.305, "d": 3.648, "kind": "line", "sub": "Whether Baldwin had a hand in it is still debated."}, {"t": 25.373, "d": 4.629, "kind": "line", "sub": "On 10 March 1098 he became Count of Edessa."}, {"t": 30.422, "d": 4.459, "kind": "line", "sub": "The County of Edessa was the first state founded by the crusaders."}, {"t": 35.301, "d": 4.395, "kind": "line", "sub": "Its money and food would help keep the army alive at Antioch."}]}, "ch:first:antioch-falls": {"src": "audio/ch-first-antioch-falls.mp3", "dur": 32.363, "cues": [{"t": 0.35, "d": 3.755, "kind": "title", "sub": "3 June 1098. Antioch falls."}, {"t": 5.005, "d": 5.995, "kind": "line", "sub": "Bohemond made a secret deal with Firuz, a convert who commanded a tower on the walls."}, {"t": 11.419, "d": 8.363, "kind": "line", "sub": "Before dawn on 3 June, a small party climbed a leather ladder into the Tower of the Two Sisters and opened a gate."}, {"t": 20.202, "d": 4.693, "kind": "line", "sub": "The city fell within hours, though its citadel on the mountain held out."}, {"t": 25.315, "d": 2.837, "kind": "line", "sub": "Bohemond claimed the city for himself."}, {"t": 28.573, "d": 3.371, "kind": "line", "sub": "It would become the Principality of Antioch."}]}, "ch:first:holy-lance": {"src": "audio/ch-first-holy-lance.mp3", "dur": 66.759, "cues": [{"t": 0.35, "d": 4.928, "kind": "title", "sub": "14–28 June 1098. The Holy Lance."}, {"t": 6.178, "d": 3.648, "kind": "line", "sub": "Two days later the besiegers became the besieged."}, {"t": 10.246, "d": 4.117, "kind": "line", "sub": "Kerbogha, ruler of Mosul, arrived with a huge army."}, {"t": 14.783, "d": 5.717, "kind": "line", "sub": "Trapped and starving, some crusaders let themselves down the walls on ropes and fled."}, {"t": 20.921, "d": 5.397, "kind": "line", "sub": "Then Peter Bartholomew, a poor pilgrim, reported visions of St Andrew."}, {"t": 26.738, "d": 6.763, "kind": "line", "sub": "On 14 June a lance point was dug up beneath the floor of the Cathedral of St Peter."}, {"t": 33.921, "d": 3.861, "kind": "line", "sub": "Many believed it was the spear that pierced Christ's side."}, {"t": 38.202, "d": 3.477, "kind": "line", "sub": "Adhemar had doubts, but the army's spirit came back."}, {"t": 42.099, "d": 9.472, "kind": "line", "sub": "After three days of fasting and processions, the army marched out on 28 June in six divisions while priests prayed on the walls."}, {"t": 51.991, "d": 3.627, "kind": "line", "sub": "Kerbogha's divided coalition broke and fled."}, {"t": 56.388, "d": 9.621, "kind": "quote", "sub": "There came out from the mountains countless armies on white horses, whose banners were all white. Their leaders were St George, St Mercurius and St Demetrius.", "source": "Gesta Francorum (abridged)"}]}, "ch:first:road-south": {"src": "audio/ch-first-road-south.mp3", "dur": 55.541, "cues": [{"t": 0.35, "d": 5.333, "kind": "title", "sub": "August 1098 – June 1099. The road to Jerusalem."}, {"t": 6.583, "d": 4.608, "kind": "line", "sub": "On 1 August 1098 Bishop Adhemar died of plague."}, {"t": 11.611, "d": 4.885, "kind": "line", "sub": "Without him, the princes quarrelled for months over who would hold Antioch."}, {"t": 16.917, "d": 9.429, "kind": "line", "sub": "That winter, at the siege of Ma'arra, famine became so severe that the chroniclers recorded, with shame, that some crusaders ate the dead."}, {"t": 26.766, "d": 2.709, "kind": "line", "sub": "The ordinary pilgrims forced the issue."}, {"t": 29.895, "d": 4.011, "kind": "line", "sub": "They tore down the walls of Ma'arra so the army could not stay."}, {"t": 34.326, "d": 6.485, "kind": "line", "sub": "In January 1099 Raymond walked out barefoot as a pilgrim and led the march south."}, {"t": 41.231, "d": 2.859, "kind": "line", "sub": "Bohemond stayed behind in Antioch."}, {"t": 44.51, "d": 4.331, "kind": "line", "sub": "After a long siege at Arqa, the army moved fast down the coast."}, {"t": 49.261, "d": 2.88, "kind": "line", "sub": "Local rulers paid them to pass by."}, {"t": 52.561, "d": 2.56, "kind": "line", "sub": "In early June they reached Ramla."}]}, "ch:first:jerusalem": {"src": "audio/ch-first-jerusalem.mp3", "dur": 68.658, "cues": [{"t": 0.35, "d": 5.227, "kind": "title", "sub": "7 June – 15 July 1099. Jerusalem."}, {"t": 6.477, "d": 4.48, "kind": "line", "sub": "On 7 June the army saw Jerusalem, and many wept."}, {"t": 11.377, "d": 7.936, "kind": "line", "sub": "Of the great host that had left, about 1,300 knights and perhaps 12,000 men on foot remained."}, {"t": 19.733, "d": 3.029, "kind": "line", "sub": "A first assault failed for lack of ladders."}, {"t": 23.182, "d": 3.008, "kind": "line", "sub": "Water was scarce and the heat was crushing."}, {"t": 26.61, "d": 5.099, "kind": "line", "sub": "When Genoese ships arrived at Jaffa, their timber went into siege towers."}, {"t": 32.129, "d": 9.408, "kind": "line", "sub": "On 8 July the whole army walked barefoot in procession around the walls, and Peter the Hermit preached to them on the Mount of Olives."}, {"t": 41.957, "d": 6.037, "kind": "line", "sub": "On 15 July Godfrey's tower reached the north wall, and the city fell that day."}, {"t": 48.414, "d": 5.888, "kind": "line", "sub": "The chroniclers record a terrible slaughter of its Muslim and Jewish inhabitants."}, {"t": 54.722, "d": 4.715, "kind": "line", "sub": "Afterwards the crusaders went to the Holy Sepulchre to give thanks."}, {"t": 60.207, "d": 7.701, "kind": "quote", "sub": "This day, I say, will be famous in all future ages, for it turned our labours and sorrows into joy and exultation.", "source": "Raymond of Aguilers, chaplain to Raymond of Toulouse"}]}, "ch:first:defender": {"src": "audio/ch-first-defender.mp3", "dur": 30.327, "cues": [{"t": 0.35, "d": 4.949, "kind": "title", "sub": "22 July 1099. A crown of thorns."}, {"t": 6.199, "d": 2.539, "kind": "line", "sub": "The leaders met to choose a ruler."}, {"t": 9.158, "d": 2.304, "kind": "line", "sub": "Raymond refused the crown."}, {"t": 11.882, "d": 1.856, "kind": "line", "sub": "They turned to Godfrey."}, {"t": 14.158, "d": 3.605, "kind": "line", "sub": "Godfrey agreed to govern but would not be called king."}, {"t": 18.183, "d": 5.717, "kind": "line", "sub": "He took the title Advocatus Sancti Sepulchri, Defender of the Holy Sepulchre."}, {"t": 24.671, "d": 4.907, "kind": "quote", "sub": "He would not wear a crown of gold where his Saviour had worn a crown of thorns.", "source": "William of Tyre, writing c. 1170–1184 (paraphrased)"}]}, "ch:first:ascalon": {"src": "audio/ch-first-ascalon.mp3", "dur": 34.81, "cues": [{"t": 0.35, "d": 4.523, "kind": "title", "sub": "12 August 1099. The battle of Ascalon."}, {"t": 5.773, "d": 6.357, "kind": "line", "sub": "A Fatimid army under the vizier al-Afdal marched from Egypt to retake Jerusalem."}, {"t": 12.55, "d": 2.581, "kind": "line", "sub": "Godfrey led the crusaders out."}, {"t": 15.551, "d": 5.632, "kind": "line", "sub": "Before them went a relic of the True Cross, found in the city only days before."}, {"t": 21.603, "d": 6.613, "kind": "line", "sub": "At dawn on 12 August they surprised the Egyptian camp outside Ascalon and routed it."}, {"t": 28.637, "d": 2.219, "kind": "line", "sub": "Jerusalem was secure."}, {"t": 31.275, "d": 3.115, "kind": "line", "sub": "The crusade had done what it set out to do."}]}, "ch:first:epilogue": {"src": "audio/ch-first-epilogue.mp3", "dur": 51.014, "cues": [{"t": 0.35, "d": 3.456, "kind": "title", "sub": "1099 and after. What came after."}, {"t": 4.706, "d": 3.819, "kind": "line", "sub": "With their vows fulfilled, most crusaders sailed home."}, {"t": 8.945, "d": 4.544, "kind": "line", "sub": "Godfrey stayed with perhaps 300 knights to hold Jerusalem."}, {"t": 13.909, "d": 6.464, "kind": "line", "sub": "He died in July 1100, and his brother Baldwin became the first King of Jerusalem."}, {"t": 20.793, "d": 9.963, "kind": "line", "sub": "Pope Urban II died in Rome on 29 July 1099, fourteen days after Jerusalem fell, before the news could reach him."}, {"t": 31.175, "d": 7.829, "kind": "line", "sub": "The crusaders' states now stood in the East: Edessa, Antioch, Jerusalem, and from 1109 Tripoli."}, {"t": 39.425, "d": 6.357, "kind": "line", "sub": "When Edessa fell in 1144, Christendom would answer again with the Second Crusade."}, {"t": 46.552, "d": 3.712, "kind": "quote", "sub": "For we who were Westerners have now become Easterners.", "source": "Fulcher of Chartres, who settled in Jerusalem"}]}, "sc:first:dorylaeum": {"src": "audio/sc-first-dorylaeum.mp3", "dur": 61.727, "cues": [{"t": 0.35, "d": 2.048, "kind": "title", "sub": "The battle of Dorylaeum."}, {"t": 3.298, "d": 11.925, "kind": "phase", "sub": "Dawn, 1 July 1097. Bohemond's half of the army has camped by a river near Dorylaeum. The other half, under Godfrey and Raymond, is some miles behind.", "phase": 0}, {"t": 15.923, "d": 7.168, "kind": "phase", "sub": "Turkish horse archers pour over the hills and surround the camp. Arrows fall like rain on the Christians.", "phase": 1}, {"t": 23.791, "d": 10.197, "kind": "phase", "sub": "Bohemond sends riders for help and orders everyone to hold together. The army draws into a tight ring, and the women carry water to the fighting men.", "phase": 2}, {"t": 34.689, "d": 8.917, "kind": "phase", "sub": "Around midday the second army arrives. Godfrey and Hugh charge in from the west, then Raymond. Now the Turks are fighting on two fronts.", "phase": 3}, {"t": 44.306, "d": 9.067, "kind": "phase", "sub": "Bishop Adhemar, who had led his men around through the hills, appears behind the Turkish camp. Caught between three forces, the Turks break.", "phase": 4}, {"t": 54.073, "d": 6.955, "kind": "phase", "sub": "Kilij Arslan flees, leaving his camp and treasure behind. The road across Anatolia is open.", "phase": 5}]}, "sc:first:antioch": {"src": "audio/sc-first-antioch.mp3", "dur": 57.55, "cues": [{"t": 0.35, "d": 2.133, "kind": "title", "sub": "The battle of Antioch."}, {"t": 3.383, "d": 11.797, "kind": "phase", "sub": "Dawn, 28 June 1098. After three days of fasting and prayer, the starving army marches out of Antioch through the Bridge Gate. Priests pray on the walls.", "phase": 0}, {"t": 15.881, "d": 8.085, "kind": "phase", "sub": "Kerbogha lets them cross, hoping to destroy the whole army at once. He sends horsemen around to strike them from behind.", "phase": 1}, {"t": 24.666, "d": 10.112, "kind": "phase", "sub": "Bohemond's division turns to hold the rear while the rest of the line advances. Raymond of Aguilers carries the Holy Lance before Adhemar's men.", "phase": 2}, {"t": 35.478, "d": 10.645, "kind": "phase", "sub": "Then, as the Gesta tells it, an army of riders on white horses came down from the mountains, led by St George, St Demetrius and St Mercurius.", "phase": 3}, {"t": 46.823, "d": 10.027, "kind": "phase", "sub": "Kerbogha's allies, already quarrelling, abandon him. His army breaks and flees. The crusaders take his camp, and that day the citadel surrenders.", "phase": 4}]}, "sc:first:jerusalem": {"src": "audio/sc-first-jerusalem.mp3", "dur": 66.634, "cues": [{"t": 0.35, "d": 2.027, "kind": "title", "sub": "The fall of Jerusalem."}, {"t": 3.277, "d": 11.435, "kind": "phase", "sub": "Night of 13 July. Godfrey's men take their siege tower apart and rebuild it opposite a weaker stretch of the north wall, east of where the defenders expect it.", "phase": 0}, {"t": 15.411, "d": 10.773, "kind": "phase", "sub": "14 July. A battering ram smashes the outer wall so the towers can roll close. The defenders answer with stones, arrows and Greek fire.", "phase": 1}, {"t": 26.885, "d": 7.424, "kind": "phase", "sub": "On Mount Zion in the south, Raymond's tower meets the fiercest defence of all. The fighting goes on all day.", "phase": 2}, {"t": 35.009, "d": 13.376, "kind": "phase", "sub": "Midday, 15 July. Godfrey's tower reaches the north wall. A bridge drops onto the wall, and the brothers Litold and Engelbert of Tournai are the first across, with Godfrey behind them.", "phase": 3}, {"t": 49.085, "d": 8.64, "kind": "phase", "sub": "The north wall falls and the crusaders pour into the city. In the south, the governor surrenders the Tower of David to Raymond.", "phase": 4}, {"t": 58.425, "d": 7.509, "kind": "phase", "sub": "When the fighting ended, the crusaders went to the Church of the Holy Sepulchre to give thanks at the tomb of Christ.", "phase": 5}]}, "sc:first:ascalon": {"src": "audio/sc-first-ascalon.mp3", "dur": 50.19, "cues": [{"t": 0.35, "d": 2.069, "kind": "title", "sub": "The battle of Ascalon."}, {"t": 3.319, "d": 13.781, "kind": "phase", "sub": "Dawn, 12 August 1099. The crusaders march south in battle order, with the newly found relic of the True Cross carried before them. Raymond holds the right by the sea, Godfrey the left.", "phase": 0}, {"t": 17.801, "d": 5.205, "kind": "phase", "sub": "Al-Afdal's army is camped before Ascalon, and the attack catches it unready.", "phase": 1}, {"t": 23.706, "d": 7.147, "kind": "phase", "sub": "Robert of Normandy charges straight at al-Afdal's standard and captures it. The whole line follows him in.", "phase": 2}, {"t": 31.553, "d": 9.899, "kind": "phase", "sub": "The Fatimid army breaks. Some flee into Ascalon, some into the sea, and some hide in the sycamore groves, which the crusaders set on fire.", "phase": 3}, {"t": 42.151, "d": 7.339, "kind": "phase", "sub": "Al-Afdal escapes by ship to Egypt. Jerusalem is safe, and the crusade has done what it set out to do.", "phase": 4}]}, "sc:first:clermont": {"src": "audio/sc-first-clermont.mp3", "dur": 51.342, "cues": [{"t": 0.35, "d": 2.347, "kind": "title", "sub": "Urban II at Clermont."}, {"t": 3.597, "d": 12.395, "kind": "phase", "sub": "27 November 1095. The council of Clermont is over. No church can hold the crowd, so Urban II speaks from a platform in a field outside the town.", "phase": 0}, {"t": 16.691, "d": 10.709, "kind": "phase", "sub": "He speaks of Eastern Christians attacked by the Turks, of churches destroyed, and of Jerusalem in foreign hands. He tells the knights to stop fighting each other.", "phase": 1}, {"t": 28.101, "d": 4.331, "kind": "phase", "sub": "The crowd answers with one cry: Deus vult! God wills it!", "phase": 2}, {"t": 33.131, "d": 6.805, "kind": "phase", "sub": "Adhemar, Bishop of Le Puy, comes forward and kneels before the pope. He is the first to take the cross.", "phase": 3}, {"t": 40.637, "d": 10.005, "kind": "phase", "sub": "Many follow him. They cut cloth into crosses and sew them on their shoulders. The council decrees that the journey will count in place of all penance.", "phase": 4}]}, "sc:first:lance": {"src": "audio/sc-first-lance.mp3", "dur": 48.889, "cues": [{"t": 0.35, "d": 2.368, "kind": "title", "sub": "The finding of the Holy Lance."}, {"t": 3.618, "d": 11.477, "kind": "phase", "sub": "14 June 1098. Peter Bartholomew, a poor pilgrim, says St Andrew showed him where the lance lies: under the floor of the Cathedral of St Peter.", "phase": 0}, {"t": 15.795, "d": 7.68, "kind": "phase", "sub": "Twelve men dig from morning until evening. They find nothing. Count Raymond leaves to keep watch on the citadel.", "phase": 1}, {"t": 24.175, "d": 6.528, "kind": "phase", "sub": "Peter Bartholomew, barefoot and in his shirt, leaps down into the pit and tells the others to pray.", "phase": 2}, {"t": 31.403, "d": 7.787, "kind": "phase", "sub": "The point of a lance appears in the earth. Raymond of Aguilers writes that he kissed it as soon as the point appeared.", "phase": 3}, {"t": 39.89, "d": 8.299, "kind": "phase", "sub": "The news spreads through the starving city. Many believe it is the spear that pierced Christ's side, and the army's spirit comes back.", "phase": 4}]}, "sc:first:procession": {"src": "audio/sc-first-procession.mp3", "dur": 50.19, "cues": [{"t": 0.35, "d": 2.709, "kind": "title", "sub": "The procession around Jerusalem."}, {"t": 3.959, "d": 11.669, "kind": "phase", "sub": "8 July 1099. After a three-day fast, the whole army sets out to walk barefoot around Jerusalem. Clergy go first, carrying crosses and relics.", "phase": 0}, {"t": 16.329, "d": 6.976, "kind": "phase", "sub": "They pass beneath the north wall singing. The defenders jeer, raise crosses on the walls and insult them.", "phase": 1}, {"t": 24.005, "d": 5.12, "kind": "phase", "sub": "The procession turns south along the east wall and climbs the Mount of Olives.", "phase": 2}, {"t": 29.825, "d": 10.133, "kind": "phase", "sub": "On the Mount of Olives, Peter the Hermit preaches to the army, and the chaplain Arnulf after him. Raymond and Tancred, long at odds, are reconciled.", "phase": 3}, {"t": 40.658, "d": 8.832, "kind": "phase", "sub": "The army returns to its camps to build ladders and towers. The final assault begins on the night of 13 July.", "phase": 4}]}, "sc:first:crown": {"src": "audio/sc-first-crown.mp3", "dur": 49.635, "cues": [{"t": 0.35, "d": 2.645, "kind": "title", "sub": "Defender of the Holy Sepulchre."}, {"t": 3.895, "d": 9.131, "kind": "phase", "sub": "22 July 1099. A week after the city fell, the princes and clergy meet to choose a ruler for Jerusalem.", "phase": 0}, {"t": 13.726, "d": 5.739, "kind": "phase", "sub": "Some of the clergy argue that a spiritual leader should be chosen first, before any king.", "phase": 1}, {"t": 20.165, "d": 9.472, "kind": "phase", "sub": "The crown is offered to Raymond of Toulouse. He refuses. Raymond of Aguilers says the count would not bear the name of king in that city.", "phase": 2}, {"t": 30.337, "d": 5.312, "kind": "phase", "sub": "The princes turn to Godfrey. He agrees to govern, but he will not be called king.", "phase": 3}, {"t": 36.349, "d": 12.587, "kind": "phase", "sub": "He takes the title Advocatus Sancti Sepulchri, Defender of the Holy Sepulchre. Later tradition says he would not wear a crown of gold where Christ had worn a crown of thorns.", "phase": 4}]}, "part:second": {"src": "audio/part-second.mp3", "dur": 15.43, "cues": [{"t": 0.35, "d": 6.037, "kind": "title", "sub": "Part Two. The Kingdom and the Second Crusade. 1100–1149."}, {"t": 7.287, "d": 7.723, "kind": "line", "sub": "Fifty years of the Latin East, the fall of Edessa, and the great crusade of two kings that broke at Damascus."}]}, "ch:second:second-prologue": {"src": "audio/ch-second-second-prologue.mp3", "dur": 56.977, "cues": [{"t": 0.35, "d": 5.589, "kind": "title", "sub": "October – 25 December 1100. A king in Bethlehem."}, {"t": 6.839, "d": 5.867, "kind": "line", "sub": "Godfrey of Bouillon died in Jerusalem on 18 July 1100."}, {"t": 13.126, "d": 4.48, "kind": "line", "sub": "His knights sent word north to his brother Baldwin, Count of Edessa."}, {"t": 18.026, "d": 6.187, "kind": "line", "sub": "Baldwin handed Edessa to his cousin, Baldwin of Bourcq, and set out with a small army."}, {"t": 24.633, "d": 6.485, "kind": "line", "sub": "Near the Dog River, north of Beirut, the ruler of Damascus laid an ambush on the coast road."}, {"t": 31.538, "d": 2.219, "kind": "line", "sub": "Baldwin fought his way through."}, {"t": 34.177, "d": 6.187, "kind": "line", "sub": "His chaplain, Fulcher of Chartres, rode with him and admitted that he was badly frightened."}, {"t": 40.783, "d": 3.819, "kind": "line", "sub": "Godfrey had refused to wear a crown in Jerusalem."}, {"t": 45.022, "d": 2.261, "kind": "line", "sub": "Baldwin had no such doubts."}, {"t": 47.703, "d": 8.853, "kind": "line", "sub": "On Christmas Day 1100, in the Church of the Nativity at Bethlehem, Patriarch Daimbert crowned him King of Jerusalem."}]}, "ch:second:second-coast": {"src": "audio/ch-second-second-coast.mp3", "dur": 84.491, "cues": [{"t": 0.35, "d": 4.459, "kind": "title", "sub": "1101–1110. The ports and the fourth state."}, {"t": 5.709, "d": 2.773, "kind": "line", "sub": "The kingdom could not live without ports."}, {"t": 8.902, "d": 7.04, "kind": "line", "sub": "Pilgrims, settlers and supplies all came by sea, and most of the coast was still in Muslim hands."}, {"t": 16.362, "d": 2.965, "kind": "line", "sub": "The Italian trading cities had the ships."}, {"t": 19.747, "d": 6.869, "kind": "line", "sub": "In return for their help, Baldwin gave them a share of the spoils and a quarter of each city to trade from."}, {"t": 27.037, "d": 4.8, "kind": "line", "sub": "With a Genoese fleet he took Arsuf and Caesarea in 1101."}, {"t": 32.257, "d": 6.037, "kind": "line", "sub": "Acre, the best harbour on the coast, surrendered on 26 May 1104."}, {"t": 38.714, "d": 9.941, "kind": "line", "sub": "Beirut fell in 1110, and Sidon that December with the help of King Sigurd of Norway, who had sailed out with a fleet of Norwegian crusaders."}, {"t": 49.075, "d": 7.616, "kind": "line", "sub": "In the north, Raymond of Toulouse had besieged Tripoli from a castle he built on a hill outside it, Mount Pilgrim."}, {"t": 57.111, "d": 2.752, "kind": "line", "sub": "He died there in 1105."}, {"t": 60.283, "d": 6.891, "kind": "line", "sub": "His son Bertrand took the city on 12 July 1109, again with Genoese ships."}, {"t": 67.594, "d": 6.741, "kind": "line", "sub": "The County of Tripoli joined Edessa, Antioch and Jerusalem as the fourth crusader state."}, {"t": 74.755, "d": 3.819, "kind": "line", "sub": "Only Tyre and Ascalon now held out on the coast."}, {"t": 78.994, "d": 5.077, "kind": "line", "sub": "Tyre fell in 1124, to a siege backed by a Venetian fleet."}]}, "ch:second:second-ager": {"src": "audio/ch-second-second-ager.mp3", "dur": 67.231, "cues": [{"t": 0.35, "d": 4.416, "kind": "title", "sub": "28 June 1119. The Field of Blood."}, {"t": 5.666, "d": 9.237, "kind": "line", "sub": "Baldwin I died in 1118 on a raid into Egypt, and his cousin Baldwin of Bourcq became King Baldwin II."}, {"t": 15.323, "d": 5.76, "kind": "line", "sub": "The next summer Ilghazi, the Turkish lord of Mardin, invaded the lands of Antioch."}, {"t": 21.503, "d": 6.165, "kind": "line", "sub": "Roger of Salerno, who governed Antioch, would not wait for the king and the Count of Tripoli."}, {"t": 28.089, "d": 2.923, "kind": "line", "sub": "He camped in a valley near Sarmada."}, {"t": 31.431, "d": 5.483, "kind": "line", "sub": "At dawn on 28 June 1119 the Turks surrounded the camp."}, {"t": 37.334, "d": 7.253, "kind": "line", "sub": "Roger was killed fighting beneath a great jewelled cross, and almost his whole army was killed or taken."}, {"t": 45.007, "d": 3.584, "kind": "line", "sub": "Many prisoners were tortured to death at Aleppo."}, {"t": 49.011, "d": 4.523, "kind": "line", "sub": "Walter, Roger's chancellor, wrote the Latin account of the battle."}, {"t": 53.954, "d": 4.224, "kind": "line", "sub": "The Franks called the place Ager Sanguinis, the Field of Blood."}, {"t": 58.598, "d": 8.213, "kind": "line", "sub": "In Antioch the patriarch armed the clergy to guard the walls until Baldwin II arrived and saved the city."}]}, "ch:second:second-templars": {"src": "audio/ch-second-second-templars.mp3", "dur": 83.535, "cues": [{"t": 0.35, "d": 4.48, "kind": "title", "sub": "1113–1120. Poor knights of the Temple."}, {"t": 5.73, "d": 3.392, "kind": "line", "sub": "Two new kinds of brotherhood grew up in Jerusalem."}, {"t": 9.542, "d": 9.344, "kind": "line", "sub": "The first was the Hospital of St John, a hostel for poor and sick pilgrims near the Holy Sepulchre, run by a man named Gerard."}, {"t": 19.306, "d": 5.163, "kind": "line", "sub": "In 1113 Pope Paschal II took it under papal protection."}, {"t": 24.889, "d": 2.347, "kind": "line", "sub": "It would later take up arms too."}, {"t": 27.655, "d": 1.984, "kind": "line", "sub": "The roads were dangerous."}, {"t": 30.059, "d": 6.571, "kind": "line", "sub": "At Easter 1119 a band of pilgrims was massacred on the way to the River Jordan."}, {"t": 37.05, "d": 11.797, "kind": "line", "sub": "Around this time Hugh of Payns, a knight from Champagne, and Godfrey of Saint-Omer, with a few companions, took vows of poverty, chastity and obedience before the patriarch."}, {"t": 49.267, "d": 2.581, "kind": "line", "sub": "Their task was to protect pilgrims."}, {"t": 52.269, "d": 7.979, "kind": "line", "sub": "King Baldwin II gave them part of his palace in the al-Aqsa mosque, which the Franks called the Temple of Solomon."}, {"t": 60.667, "d": 2.048, "kind": "line", "sub": "From it they took their name."}, {"t": 63.135, "d": 7.616, "kind": "line", "sub": "William of Tyre says they were only nine for their first nine years, and wore ordinary clothes given them as alms."}, {"t": 71.521, "d": 11.264, "kind": "quote", "sub": "Their primary duty was that, as far as their strength permitted, they should keep the roads and highways safe from the menace of robbers and highwaymen, with especial regard for the protection of pilgrims.", "source": "William of Tyre, History, book 12 (abridged)"}]}, "ch:second:second-troyes": {"src": "audio/ch-second-second-troyes.mp3", "dur": 67.969, "cues": [{"t": 0.35, "d": 5.141, "kind": "title", "sub": "13 January 1129. The Council of Troyes."}, {"t": 6.391, "d": 5.141, "kind": "line", "sub": "In 1127 Hugh of Payns sailed west to raise men and money."}, {"t": 11.953, "d": 7.147, "kind": "line", "sub": "King Baldwin II also gave him a second errand: to find a husband for his daughter Melisende."}, {"t": 19.519, "d": 3.477, "kind": "line", "sub": "Hugh helped bring Count Fulk of Anjou into the match."}, {"t": 23.417, "d": 6.101, "kind": "line", "sub": "In January 1129 a church council met at Troyes under the papal legate."}, {"t": 29.938, "d": 3.755, "kind": "line", "sub": "Bernard, abbot of the nearby abbey of Clairvaux, was there."}, {"t": 34.113, "d": 5.205, "kind": "line", "sub": "The council gave the Templars a rule, drawn partly from the customs of monks."}, {"t": 39.738, "d": 2.091, "kind": "line", "sub": "Their knights would wear white."}, {"t": 42.249, "d": 4.16, "kind": "line", "sub": "At Hugh's request Bernard wrote In Praise of the New Knighthood."}, {"t": 46.829, "d": 4.117, "kind": "line", "sub": "It praised a new kind of man, a knight who was also a monk."}, {"t": 51.366, "d": 5.397, "kind": "line", "sub": "Gifts of land and money soon poured in, and Hugh went back east with new brothers."}, {"t": 57.533, "d": 9.685, "kind": "quote", "sub": "He is truly a fearless knight and secure on every side, for his soul is protected by the armour of faith just as his body is protected by armour of steel.", "source": "Bernard of Clairvaux, In Praise of the New Knighthood"}]}, "ch:second:second-melisende": {"src": "audio/ch-second-second-melisende.mp3", "dur": 62.082, "cues": [{"t": 0.35, "d": 4.459, "kind": "title", "sub": "1129–1143. Queen Melisende."}, {"t": 5.709, "d": 4.501, "kind": "line", "sub": "Melisende married Fulk of Anjou in 1129."}, {"t": 10.63, "d": 8.896, "kind": "line", "sub": "When Baldwin II died in August 1131 he left the kingdom to Melisende, Fulk and their baby son together."}, {"t": 19.946, "d": 3.755, "kind": "line", "sub": "They were crowned in the Holy Sepulchre that September."}, {"t": 24.121, "d": 2.667, "kind": "line", "sub": "Fulk tried to rule without his wife."}, {"t": 27.207, "d": 13.248, "kind": "line", "sub": "A revolt by her kinsman Hugh of Le Puiset in 1134 ended in her favour, and William of Tyre says that afterwards Fulk did nothing, even in small matters, without her consent."}, {"t": 40.875, "d": 7.019, "kind": "line", "sub": "She founded a convent at Bethany for her youngest sister and gave richly to the churches of Jerusalem."}, {"t": 48.314, "d": 6.549, "kind": "line", "sub": "In November 1143 Fulk was killed when his horse fell while chasing a hare near Acre."}, {"t": 55.283, "d": 6.379, "kind": "line", "sub": "At Christmas Melisende was crowned again, with her thirteen-year-old son, Baldwin III."}]}, "ch:second:second-zengi": {"src": "audio/ch-second-second-zengi.mp3", "dur": 57.858, "cues": [{"t": 0.35, "d": 4.075, "kind": "title", "sub": "1127–1144. Zengi."}, {"t": 5.325, "d": 6.635, "kind": "line", "sub": "For thirty years the Franks had survived partly because the Muslim rulers of Syria were divided."}, {"t": 12.379, "d": 8.405, "kind": "line", "sub": "That began to change in 1127, when the Turkish commander Imad ad-Din Zengi became ruler of Mosul."}, {"t": 21.205, "d": 2.56, "kind": "line", "sub": "A year later he took Aleppo."}, {"t": 24.185, "d": 7.872, "kind": "line", "sub": "In 1137 he trapped King Fulk in the castle of Montferrand and let him go only in exchange for it."}, {"t": 32.477, "d": 2.965, "kind": "line", "sub": "Zengi wanted Damascus most of all."}, {"t": 35.862, "d": 8.427, "kind": "line", "sub": "Its ruler, Unur, turned to Jerusalem for help, and in 1140 Damascenes and Franks besieged Banias together."}, {"t": 44.709, "d": 7.296, "kind": "line", "sub": "In the far north, Count Joscelin II of Edessa kept his court at Turbessel, west of the Euphrates."}, {"t": 52.425, "d": 5.013, "kind": "line", "sub": "William of Tyre, writing later, blamed him for neglecting his capital."}]}, "ch:second:second-edessa": {"src": "audio/ch-second-second-edessa.mp3", "dur": 75.062, "cues": [{"t": 0.35, "d": 6.912, "kind": "title", "sub": "28 November – 24 December 1144. The fall of Edessa."}, {"t": 8.162, "d": 6.144, "kind": "line", "sub": "In late 1144 Joscelin II took his troops west of the Euphrates."}, {"t": 14.726, "d": 5.013, "kind": "line", "sub": "Zengi moved fast and was before Edessa on 28 November."}, {"t": 20.159, "d": 2.24, "kind": "line", "sub": "The city had few soldiers."}, {"t": 22.819, "d": 6.763, "kind": "line", "sub": "Its Latin archbishop, Hugh, led the defence with the Armenian and Syrian bishops and the townsmen."}, {"t": 30.002, "d": 4.992, "kind": "line", "sub": "Zengi's miners dug under the north wall and propped their tunnels with timber."}, {"t": 35.414, "d": 5.568, "kind": "line", "sub": "On 24 December they fired the props and a long stretch of wall fell."}, {"t": 41.402, "d": 1.6, "kind": "line", "sub": "The Turks poured in."}, {"t": 43.422, "d": 6.272, "kind": "line", "sub": "Many townspeople were crushed in the rush to the citadel, and Archbishop Hugh was among the dead."}, {"t": 50.114, "d": 2.795, "kind": "line", "sub": "The citadel surrendered two days later."}, {"t": 53.329, "d": 4.032, "kind": "line", "sub": "Zengi put the Franks to death and spared the native Christians."}, {"t": 57.781, "d": 2.688, "kind": "line", "sub": "Help from Jerusalem came too late."}, {"t": 60.889, "d": 6.165, "kind": "line", "sub": "In 1146 Zengi was murdered, and Joscelin briefly got back into the city."}, {"t": 67.474, "d": 7.168, "kind": "line", "sub": "Zengi's son Nur ad-Din retook it, and this time the Christian population was killed or carried off."}]}, "ch:second:second-bull": {"src": "audio/ch-second-second-bull.mp3", "dur": 78.749, "cues": [{"t": 0.35, "d": 7.979, "kind": "title", "sub": "1 December 1145 – 1 March 1146. Quantum praedecessores."}, {"t": 9.229, "d": 8.661, "kind": "line", "sub": "Envoys from the East brought the news to Pope Eugenius III, who was living outside Rome after its citizens drove him out."}, {"t": 18.31, "d": 10.048, "kind": "line", "sub": "On 1 December 1145 he issued a bull, known from its first words as Quantum praedecessores, \"How much our predecessors\"."}, {"t": 28.778, "d": 5.867, "kind": "line", "sub": "It recalled the First Crusade and called on the French to defend what their fathers had won."}, {"t": 35.065, "d": 5.099, "kind": "line", "sub": "Crusaders' wives, children and property would be under the Church's protection."}, {"t": 40.583, "d": 5.717, "kind": "line", "sub": "Interest on their debts was suspended, and they could pledge their lands to raise money."}, {"t": 46.721, "d": 4.736, "kind": "line", "sub": "They should go plainly, without fine clothes, hunting dogs or hawks."}, {"t": 51.877, "d": 5.397, "kind": "line", "sub": "At Christmas, at Bourges, King Louis VII told his barons he meant to go."}, {"t": 57.694, "d": 1.195, "kind": "line", "sub": "They were cool."}, {"t": 59.309, "d": 7.339, "kind": "line", "sub": "The pope reissued the bull on 1 March 1146 and asked Bernard of Clairvaux to preach it."}, {"t": 67.417, "d": 10.581, "kind": "quote", "sub": "Whoever shall devoutly begin and complete so holy a journey, or shall die on it, shall obtain absolution for all his sins which he has confessed with a contrite and humble heart.", "source": "Eugenius III, Quantum praedecessores (abridged)"}]}, "ch:second:second-vezelay": {"src": "audio/ch-second-second-vezelay.mp3", "dur": 59.858, "cues": [{"t": 0.35, "d": 4.288, "kind": "title", "sub": "31 March 1146. Vézelay."}, {"t": 5.538, "d": 7.381, "kind": "line", "sub": "The crowd at Vézelay was too big for the abbey church, so a wooden platform was built in a field below the hill."}, {"t": 13.339, "d": 4.907, "kind": "line", "sub": "Bernard climbed it with King Louis, who already wore a cross the pope had sent him."}, {"t": 18.666, "d": 2.731, "kind": "line", "sub": "Bernard read the pope's letter and preached."}, {"t": 21.817, "d": 2.155, "kind": "line", "sub": "The people cried out for crosses."}, {"t": 24.391, "d": 4.48, "kind": "line", "sub": "Many great lords took the cross that day, and so did Queen Eleanor."}, {"t": 29.291, "d": 8.768, "kind": "line", "sub": "Odo of Deuil, a monk of Saint-Denis who would ride east as the king's chaplain, recorded what happened when the crosses ran out."}, {"t": 38.829, "d": 7.936, "kind": "quote", "sub": "Since the packet of crosses which had been prepared beforehand was exhausted, he was forced to tear his clothes into crosses and sow them.", "source": "Odo of Deuil, De profectione Ludovici VII in Orientem, book 1"}, {"t": 47.865, "d": 11.243, "kind": "quote", "sub": "I opened my mouth; I spoke; and at once the crusaders have multiplied to infinity. Villages and towns are now deserted. You will scarcely find one man for every seven women.", "source": "Bernard of Clairvaux, letter to Eugenius III (abridged)"}]}, "ch:second:second-germany": {"src": "audio/ch-second-second-germany.mp3", "dur": 73.466, "cues": [{"t": 0.35, "d": 5.888, "kind": "title", "sub": "Autumn 1146 – spring 1147. Bernard in Germany."}, {"t": 7.138, "d": 7.808, "kind": "line", "sub": "A Cistercian monk named Radulf went preaching through the Rhineland without leave and urged attacks on the Jews."}, {"t": 15.366, "d": 4.885, "kind": "line", "sub": "Bernard came in person, silenced him and sent him back to his monastery."}, {"t": 20.671, "d": 4.8, "kind": "line", "sub": "Bernard preached through the Rhineland that winter, often through interpreters."}, {"t": 25.891, "d": 5.141, "kind": "line", "sub": "Conrad III, King of Germany, had troubles at home and was reluctant."}, {"t": 31.453, "d": 8.533, "kind": "line", "sub": "At Speyer, on 27 December 1146, after a sermon from Bernard aimed straight at him, he took the cross."}, {"t": 40.406, "d": 3.947, "kind": "line", "sub": "His nephew Frederick, later called Barbarossa, did too."}, {"t": 44.773, "d": 7.808, "kind": "line", "sub": "In March 1147 the Saxon lords asked to fight the pagan Wends on their own eastern border instead."}, {"t": 53.001, "d": 2.091, "kind": "line", "sub": "Bernard and the pope agreed."}, {"t": 55.511, "d": 3.371, "kind": "line", "sub": "The Wendish Crusade that summer achieved little."}, {"t": 59.302, "d": 3.989, "kind": "line", "sub": "Eugenius also blessed war against the Moors in Spain."}, {"t": 63.711, "d": 3.584, "kind": "line", "sub": "The crusade now ran from the Baltic to the Tagus."}, {"t": 68.065, "d": 4.651, "kind": "quote", "sub": "The Jews are not to be persecuted, killed, or even put to flight.", "source": "Bernard of Clairvaux, letter to the people of England and Germany"}]}, "ch:second:second-march": {"src": "audio/ch-second-second-march.mp3", "dur": 70.806, "cues": [{"t": 0.35, "d": 4.587, "kind": "title", "sub": "May – October 1147. Two kings on the road."}, {"t": 5.837, "d": 4.48, "kind": "line", "sub": "Conrad set out from Regensburg in May 1147."}, {"t": 10.737, "d": 12.096, "kind": "line", "sub": "On 11 June Louis took the oriflamme, the sacred banner of Saint-Denis, from the altar of the abbey with Pope Eugenius present, and left Abbot Suger to govern France."}, {"t": 23.253, "d": 4.949, "kind": "line", "sub": "Both armies marched down the Danube through Hungary and into Byzantine lands."}, {"t": 28.622, "d": 5.312, "kind": "line", "sub": "The Germans went first, and fought with Byzantine troops over food in Thrace."}, {"t": 34.354, "d": 3.477, "kind": "line", "sub": "In September a flash flood swept through their camp."}, {"t": 38.251, "d": 5.995, "kind": "line", "sub": "Conrad reached Constantinople that month and crossed to Asia without waiting for the French."}, {"t": 44.666, "d": 2.923, "kind": "line", "sub": "Louis arrived on 4 October."}, {"t": 48.009, "d": 3.413, "kind": "line", "sub": "Emperor Manuel I received him with honour."}, {"t": 51.842, "d": 6.656, "kind": "line", "sub": "Some French lords, angry that Manuel had made a truce with the Turks, urged an attack on the city."}, {"t": 58.918, "d": 1.451, "kind": "line", "sub": "Louis refused."}, {"t": 61.139, "d": 8.917, "kind": "quote", "sub": "Constantinople, the glory of the Greeks, rich in renown and richer still in possessions, is laid out in a triangular shape like a ship's sail.", "source": "Odo of Deuil, De profectione Ludovici VII in Orientem, book 4"}]}, "ch:second:second-lisbon": {"src": "audio/ch-second-second-lisbon.mp3", "dur": 81.675, "cues": [{"t": 0.35, "d": 5.781, "kind": "title", "sub": "May – 24 October 1147. The siege of Lisbon."}, {"t": 7.031, "d": 6.08, "kind": "line", "sub": "In May 1147 a fleet of over 150 ships left Dartmouth."}, {"t": 13.531, "d": 10.197, "kind": "line", "sub": "Its crusaders came from England, Normandy, Flanders and the Rhineland, and they bound themselves by a sworn compact to keep the peace among themselves."}, {"t": 24.149, "d": 9.323, "kind": "line", "sub": "At Porto, the bishop preached to them on behalf of Afonso Henriques, King of Portugal, and asked them to help take Lisbon from the Moors."}, {"t": 33.891, "d": 7.253, "kind": "line", "sub": "They reached the Tagus at the end of June and agreed terms: the plunder to the crusaders, the city to the king."}, {"t": 41.565, "d": 3.755, "kind": "line", "sub": "Some wanted to sail on, but most were persuaded to stay."}, {"t": 45.739, "d": 2.453, "kind": "line", "sub": "The siege lasted four months."}, {"t": 48.613, "d": 4.437, "kind": "line", "sub": "The Flemings and Germans brought down part of the wall with a mine."}, {"t": 53.47, "d": 4.139, "kind": "line", "sub": "The English and Normans pushed a siege tower to the wall."}, {"t": 58.029, "d": 4.011, "kind": "line", "sub": "On 24 October the starving city surrendered."}, {"t": 62.459, "d": 5.525, "kind": "line", "sub": "Some of the Flemish and Rhineland crusaders broke the terms and sacked the city."}, {"t": 68.405, "d": 3.349, "kind": "line", "sub": "The old Christian bishop of Lisbon was killed."}, {"t": 72.174, "d": 4.117, "kind": "line", "sub": "An Englishman, Gilbert of Hastings, became its new bishop."}, {"t": 76.711, "d": 4.544, "kind": "line", "sub": "Many of the crusaders sailed on to the Holy Land the next spring."}]}, "ch:second:second-dorylaeum": {"src": "audio/ch-second-second-dorylaeum.mp3", "dur": 63.391, "cues": [{"t": 0.35, "d": 5.291, "kind": "title", "sub": "October – November 1147. Conrad's army destroyed."}, {"t": 6.541, "d": 10.56, "kind": "line", "sub": "Conrad set out from Nicaea in mid-October on the old road across Anatolia, where the First Crusade had won its great battle fifty years before."}, {"t": 17.521, "d": 5.163, "kind": "line", "sub": "His army carried food for only about eight days, and the country was dry."}, {"t": 23.103, "d": 6.592, "kind": "line", "sub": "Near Dorylaeum, about 25 October, the Turks began to attack the column from all sides."}, {"t": 30.115, "d": 3.392, "kind": "line", "sub": "Men and horses weakened from hunger and thirst."}, {"t": 33.927, "d": 2.773, "kind": "line", "sub": "Conrad's lords decided to go back."}, {"t": 37.121, "d": 4.715, "kind": "line", "sub": "The retreat to Nicaea became a rout, and most of the army was lost."}, {"t": 42.255, "d": 3.2, "kind": "line", "sub": "Conrad himself was wounded by arrows."}, {"t": 45.875, "d": 5.717, "kind": "line", "sub": "A second German column, which had taken a coastal road, was also cut to pieces."}, {"t": 52.013, "d": 4.096, "kind": "line", "sub": "Conrad met Louis near Lopadion and joined him for a time."}, {"t": 56.529, "d": 6.443, "kind": "line", "sub": "Then he fell ill at Ephesus and went back to Constantinople, where Manuel nursed him himself."}]}, "ch:second:second-cadmus": {"src": "audio/ch-second-second-cadmus.mp3", "dur": 63.541, "cues": [{"t": 0.35, "d": 3.371, "kind": "title", "sub": "January 1148. Mount Cadmus."}, {"t": 4.621, "d": 7.979, "kind": "line", "sub": "Louis took the longer road down the Aegean coast, through Pergamum, Smyrna and Ephesus, where the army kept Christmas."}, {"t": 13.019, "d": 7.445, "kind": "line", "sub": "In early January it beat a Turkish force at a crossing of the Meander and pushed on past Laodicea."}, {"t": 20.885, "d": 4.352, "kind": "line", "sub": "At Mount Cadmus the king ordered the vanguard to camp on the heights."}, {"t": 25.657, "d": 4.949, "kind": "line", "sub": "Its commander, Geoffrey of Rancon, went over the summit and camped beyond."}, {"t": 31.026, "d": 4.715, "kind": "line", "sub": "The Turks seized the ground between and fell on the baggage and the foot."}, {"t": 36.161, "d": 3.691, "kind": "line", "sub": "Louis rode up with his guard, which was cut down around him."}, {"t": 40.271, "d": 8.192, "kind": "line", "sub": "Odo of Deuil says he escaped by scrambling up a rock, holding on to tree roots, and fought off his attackers until dark."}, {"t": 48.883, "d": 3.84, "kind": "line", "sub": "The army put itself under the Templars who rode with it."}, {"t": 53.143, "d": 6.997, "kind": "line", "sub": "Their master, Everard des Barres, divided it into companies of fifty, each under a brother of the Temple."}, {"t": 60.561, "d": 2.56, "kind": "line", "sub": "In that order it reached Attalia."}]}, "ch:second:second-antioch": {"src": "audio/ch-second-second-antioch.mp3", "dur": 70.511, "cues": [{"t": 0.35, "d": 4.544, "kind": "title", "sub": "January – May 1148. Attalia and Antioch."}, {"t": 5.794, "d": 2.453, "kind": "line", "sub": "Attalia was a Byzantine port."}, {"t": 8.667, "d": 4.331, "kind": "line", "sub": "Food was scarce and dear, and there were not enough ships for everyone."}, {"t": 13.418, "d": 2.752, "kind": "line", "sub": "Louis sailed with his lords and knights."}, {"t": 16.59, "d": 6.528, "kind": "line", "sub": "He paid the Greeks to escort the foot soldiers and pilgrims overland, but they were left to the Turks."}, {"t": 23.538, "d": 1.152, "kind": "line", "sub": "Many died."}, {"t": 25.11, "d": 6.165, "kind": "line", "sub": "Odo says some found more pity among the Turks than among the Greeks, and went over to them."}, {"t": 31.695, "d": 6.784, "kind": "line", "sub": "Louis landed at St Symeon, the port of Antioch, on 19 March 1148."}, {"t": 38.899, "d": 6.891, "kind": "line", "sub": "Prince Raymond, Eleanor's uncle, welcomed him and urged an attack on Aleppo, Nur ad-Din's city."}, {"t": 46.21, "d": 1.451, "kind": "line", "sub": "Louis refused."}, {"t": 48.081, "d": 2.688, "kind": "line", "sub": "He had vowed to go to Jerusalem."}, {"t": 51.189, "d": 4.011, "kind": "line", "sub": "Eleanor took her uncle's side and spoke of ending the marriage."}, {"t": 55.619, "d": 2.965, "kind": "line", "sub": "Louis took her away from Antioch by night."}, {"t": 59.005, "d": 5.312, "kind": "line", "sub": "William of Tyre and John of Salisbury both report the rumours that followed."}, {"t": 64.737, "d": 5.355, "kind": "line", "sub": "Meanwhile Conrad sailed from Constantinople and landed at Acre in April."}]}, "ch:second:second-damascus": {"src": "audio/ch-second-second-damascus.mp3", "dur": 75.266, "cues": [{"t": 0.35, "d": 6.976, "kind": "title", "sub": "24 June – 28 July 1148. The siege of Damascus."}, {"t": 8.226, "d": 16.128, "kind": "line", "sub": "On 24 June 1148 a great council met at Palmarea near Acre: Conrad, Louis, the young Baldwin III, Queen Melisende, the patriarch, the masters of the Temple and the Hospital, and the barons of the kingdom."}, {"t": 24.774, "d": 7.851, "kind": "line", "sub": "They chose to attack Damascus, the richest city in reach, though its ruler had been Jerusalem's ally against Zengi."}, {"t": 33.045, "d": 4.949, "kind": "line", "sub": "The army gathered at Tiberias and marched by Banias round Mount Hermon."}, {"t": 38.414, "d": 9.344, "kind": "line", "sub": "On 24 July it came up through the orchards west of Damascus, a maze of mud walls and lanes where defenders lay in wait."}, {"t": 48.178, "d": 5.675, "kind": "line", "sub": "The Germans fought their way on foot to the river, and the army camped among the trees."}, {"t": 54.273, "d": 5.824, "kind": "line", "sub": "Then the leaders moved the army round to the east side, where the walls were said to be weaker."}, {"t": 60.517, "d": 5.184, "kind": "line", "sub": "There was no water there, and the orchards behind them filled with the enemy again."}, {"t": 66.121, "d": 8.725, "kind": "line", "sub": "With Nur ad-Din's army on its way, the crusaders retreated on 28 July, harassed all the way back to Galilee."}]}, "ch:second:second-epilogue": {"src": "audio/ch-second-second-epilogue.mp3", "dur": 80.203, "cues": [{"t": 0.35, "d": 4.288, "kind": "title", "sub": "1148–1154. After the failure."}, {"t": 5.538, "d": 3.691, "kind": "line", "sub": "Conrad sailed home in September 1148."}, {"t": 9.649, "d": 5.013, "kind": "line", "sub": "Louis kept Easter in Jerusalem in 1149 and then left."}, {"t": 15.082, "d": 6.464, "kind": "line", "sub": "He and Eleanor travelled home on separate ships, and their marriage was annulled in 1152."}, {"t": 21.966, "d": 4.331, "kind": "line", "sub": "Eleanor married Henry of Anjou, the future King of England."}, {"t": 26.717, "d": 3.413, "kind": "line", "sub": "In the West the failure was felt as a judgment."}, {"t": 30.55, "d": 6.421, "kind": "line", "sub": "Bernard defended his preaching and said the crusaders' own sins had brought the disaster on them."}, {"t": 37.391, "d": 6.741, "kind": "line", "sub": "In the East, Nur ad-Din killed Raymond of Antioch at Inab in June 1149."}, {"t": 44.553, "d": 7.061, "kind": "line", "sub": "Joscelin II was captured the next year, and the last of his county was sold to the Byzantines."}, {"t": 52.034, "d": 5.696, "kind": "line", "sub": "In 1154 Nur ad-Din took Damascus, and Muslim Syria was one."}, {"t": 58.15, "d": 2.752, "kind": "line", "sub": "The kingdom still had victories ahead."}, {"t": 61.322, "d": 3.947, "kind": "line", "sub": "Baldwin III took Ascalon in 1153."}, {"t": 65.689, "d": 3.243, "kind": "line", "sub": "But the Franks now faced a united enemy."}, {"t": 69.351, "d": 10.432, "kind": "line", "sub": "Nur ad-Din's general Shirkuh and his nephew Saladin would carry that unity into Egypt, and in 1187 Saladin would take Jerusalem."}]}, "sc:second:templars": {"src": "audio/sc-second-templars.mp3", "dur": 59.022, "cues": [{"t": 0.35, "d": 2.325, "kind": "title", "sub": "The Poor Knights of the Temple."}, {"t": 3.575, "d": 13.952, "kind": "phase", "sub": "Jerusalem, around 1120. Pilgrims come up from the coast in their thousands, but the roads are not safe. At Easter 1119 a band of pilgrims was massacred on the way to the Jordan.", "phase": 0}, {"t": 18.227, "d": 12.117, "kind": "phase", "sub": "Hugh of Payns, a knight from Champagne, comes to the Temple Mount with Godfrey of Saint-Omer and a few companions. They stand before King Baldwin II and Patriarch Warmund.", "phase": 1}, {"t": 31.045, "d": 8.128, "kind": "phase", "sub": "They vow poverty, chastity and obedience, like canons, and take on one duty: to keep the roads safe for pilgrims.", "phase": 2}, {"t": 39.873, "d": 8.96, "kind": "phase", "sub": "The king gives them a home in his palace in the al-Aqsa mosque, which the Franks call the Temple of Solomon. From it they take their name.", "phase": 3}, {"t": 49.533, "d": 8.789, "kind": "phase", "sub": "For nine years, says William of Tyre, they were only nine. They ride out to guard the pilgrims on the road to Jaffa and the Jordan.", "phase": 4}]}, "sc:second:edessa": {"src": "audio/sc-second-edessa.mp3", "dur": 70.517, "cues": [{"t": 0.35, "d": 1.792, "kind": "title", "sub": "The fall of Edessa."}, {"t": 3.042, "d": 14.869, "kind": "phase", "sub": "28 November 1144. Zengi arrives before Edessa with a large army. Count Joscelin is away at Turbessel, beyond the Euphrates, and the defence falls to Archbishop Hugh and the townsmen.", "phase": 0}, {"t": 18.611, "d": 8.981, "kind": "phase", "sub": "Zengi's engines batter the walls day and night. His miners begin a tunnel beneath the north wall and prop it with timber as they dig.", "phase": 1}, {"t": 28.293, "d": 10.624, "kind": "phase", "sub": "Everyone who can stand fights on the walls: Franks, Armenians and Syrians, with priests and monks among them. Messengers ride for Jerusalem and Antioch.", "phase": 2}, {"t": 39.617, "d": 8.96, "kind": "phase", "sub": "24 December. The miners fire the timber props. The tunnel caves in, and a long stretch of the north wall comes down with it.", "phase": 3}, {"t": 49.277, "d": 9.429, "kind": "phase", "sub": "Zengi's men storm the breach. Townspeople run for the citadel, and many are crushed in the crowd at its gate. Archbishop Hugh is among the dead.", "phase": 4}, {"t": 59.406, "d": 10.411, "kind": "phase", "sub": "The citadel surrenders two days later. Zengi puts the Franks to death and spares the native Christians. The first crusader state has lost its capital.", "phase": 5}]}, "sc:second:vezelay1146": {"src": "audio/sc-second-vezelay1146.mp3", "dur": 48.59, "cues": [{"t": 0.35, "d": 2.453, "kind": "title", "sub": "Bernard preaches at Vézelay."}, {"t": 3.703, "d": 13.888, "kind": "phase", "sub": "Easter Sunday, 31 March 1146. So many people come to Vézelay that the abbey church cannot hold them. They gather in a field below the hill, where a wooden platform has been built.", "phase": 0}, {"t": 18.291, "d": 8.725, "kind": "phase", "sub": "Bernard of Clairvaux climbs the platform with King Louis VII. The king already wears a cross sent to him by Pope Eugenius.", "phase": 1}, {"t": 27.717, "d": 5.525, "kind": "phase", "sub": "Bernard reads the pope's letter and preaches. The crowd begins to shout for crosses.", "phase": 2}, {"t": 33.942, "d": 5.077, "kind": "phase", "sub": "The great lords come forward to take the cross, and Queen Eleanor takes it with them.", "phase": 3}, {"t": 39.719, "d": 8.171, "kind": "phase", "sub": "The crosses run out. Odo of Deuil says Bernard tore up his own clothes to make more, and went on giving them out until night.", "phase": 4}]}, "sc:second:lisbon": {"src": "audio/sc-second-lisbon.mp3", "dur": 65.589, "cues": [{"t": 0.35, "d": 1.899, "kind": "title", "sub": "The siege of Lisbon."}, {"t": 3.149, "d": 14.592, "kind": "phase", "sub": "28 June 1147. The crusader fleet sails up the Tagus to Lisbon. King Afonso Henriques of Portugal meets them, and they agree terms: the plunder to the crusaders, the city to the king.", "phase": 0}, {"t": 18.441, "d": 8.341, "kind": "phase", "sub": "1 July. The crusaders land, take the suburbs, and pitch camp on both sides of the city. The siege begins.", "phase": 1}, {"t": 27.482, "d": 6.613, "kind": "phase", "sub": "All summer the attacks are beaten back and the engines burn. Inside the walls, food runs out.", "phase": 2}, {"t": 34.795, "d": 8.789, "kind": "phase", "sub": "October. The Flemings and Germans dig a mine under the eastern wall and fire it. The wall falls, but the garrison holds the breach.", "phase": 3}, {"t": 44.285, "d": 9.173, "kind": "phase", "sub": "The English and Normans push their siege tower up to the wall by the river. Cut off by the tide for a time, it finally reaches the wall.", "phase": 4}, {"t": 54.158, "d": 10.731, "kind": "phase", "sub": "With the tower's bridge ready to drop onto the wall, the starving defenders ask for terms. Lisbon surrenders on 24 October 1147.", "phase": 5}]}, "sc:second:cadmus": {"src": "audio/sc-second-cadmus.mp3", "dur": 67.509, "cues": [{"t": 0.35, "d": 1.301, "kind": "title", "sub": "Mount Cadmus."}, {"t": 2.551, "d": 10.901, "kind": "phase", "sub": "January 1148. The French column climbs Mount Cadmus. The king has ordered the vanguard to halt on the heights and camp there, so the army can cross together.", "phase": 0}, {"t": 14.153, "d": 11.819, "kind": "phase", "sub": "Geoffrey of Rancon, who leads the vanguard, reaches the heights early and goes on over the summit to camp beyond. The column stretches out, and the baggage crowds the narrow track.", "phase": 1}, {"t": 26.671, "d": 8.555, "kind": "phase", "sub": "The Turks seize the heights between the two halves of the army and fall on the baggage. Men and pack animals are driven over the edge.", "phase": 2}, {"t": 35.926, "d": 11.691, "kind": "phase", "sub": "The king rides up with his guard into the fight. His guard is cut down around him. Odo says Louis scrambled up a rock, holding on to tree roots, and fought off his attackers alone.", "phase": 3}, {"t": 48.317, "d": 7.147, "kind": "phase", "sub": "Night falls. The Turks draw off to plunder the baggage, and Louis finds his way in the dark to the vanguard's camp.", "phase": 4}, {"t": 56.163, "d": 10.645, "kind": "phase", "sub": "The army puts itself under the Templars. Their master, Everard des Barres, divides it into companies of fifty, and the march to Attalia goes on in order.", "phase": 5}]}, "sc:second:damascus": {"src": "audio/sc-second-damascus.mp3", "dur": 70.965, "cues": [{"t": 0.35, "d": 2.069, "kind": "title", "sub": "The siege of Damascus."}, {"t": 3.319, "d": 15.744, "kind": "phase", "sub": "24 July 1148. The crusaders come up from the south-west. Baldwin III and the barons of Jerusalem lead, Louis follows, and Conrad brings up the rear. Before them lie the orchards of Damascus.", "phase": 0}, {"t": 19.763, "d": 9.301, "kind": "phase", "sub": "The orchards are a maze of mud walls and narrow lanes. Defenders hide behind the walls and spear the riders through gaps as they pass.", "phase": 1}, {"t": 29.765, "d": 10.091, "kind": "phase", "sub": "Conrad's Germans dismount and fight their way through on foot to the river. The defenders fall back behind the walls, and the army camps among the trees.", "phase": 2}, {"t": 40.555, "d": 8.021, "kind": "phase", "sub": "Turkish reinforcements ride into the city from the north. The townsmen sally out, and the orchards fill with enemies again.", "phase": 3}, {"t": 49.277, "d": 10.24, "kind": "phase", "sub": "27 July. The leaders move the whole army round to the east side, where the walls are said to be weaker. There is no water there and no shelter.", "phase": 4}, {"t": 60.217, "d": 10.048, "kind": "phase", "sub": "With Nur ad-Din's army on the way, the crusaders give up on 28 July. Horse archers harass them all the way back to Galilee.", "phase": 5}]}, "part:third": {"src": "audio/part-third.mp3", "dur": 13.681, "cues": [{"t": 0.35, "d": 5.269, "kind": "title", "sub": "Part Three. The Third Crusade. 1187–1192."}, {"t": 6.519, "d": 6.741, "kind": "line", "sub": "Jerusalem falls to Saladin, and the kings of England, France and Germany march to win it back."}]}, "ch:third:third-leper-king": {"src": "audio/ch-third-third-leper-king.mp3", "dur": 57.254, "cues": [{"t": 0.35, "d": 2.859, "kind": "title", "sub": "1174. The leper king."}, {"t": 4.109, "d": 10.283, "kind": "line", "sub": "Seventy-five years after the First Crusade, the Kingdom of Jerusalem held the coast from Beirut to Gaza and a line of castles beyond the Jordan."}, {"t": 14.811, "d": 7.829, "kind": "line", "sub": "In July 1174 King Amalric died, and his thirteen-year-old son was crowned Baldwin IV."}, {"t": 23.061, "d": 4.864, "kind": "line", "sub": "William of Tyre, the boy's tutor, tells how he first noticed the illness."}, {"t": 28.345, "d": 5.504, "kind": "line", "sub": "When the prince played rough games with other boys, he felt nothing when they scratched his arm."}, {"t": 34.269, "d": 2.368, "kind": "line", "sub": "Doctors treated him for years."}, {"t": 37.057, "d": 3.307, "kind": "line", "sub": "It was leprosy, and it grew worse as he grew up."}, {"t": 40.783, "d": 3.179, "kind": "line", "sub": "That same year, Saladin entered Damascus."}, {"t": 44.382, "d": 7.168, "kind": "line", "sub": "He had ruled Egypt since 1169 and ended its Fatimid caliphate in 1171."}, {"t": 51.97, "d": 4.864, "kind": "line", "sub": "Now one man held Cairo and Damascus, and the kingdom lay between them."}]}, "ch:third:third-montgisard": {"src": "audio/ch-third-third-montgisard.mp3", "dur": 59.679, "cues": [{"t": 0.35, "d": 4.885, "kind": "title", "sub": "25 November 1177. Montgisard."}, {"t": 6.135, "d": 6.165, "kind": "line", "sub": "In November 1177 Saladin marched out of Egypt with a large army."}, {"t": 12.721, "d": 6.421, "kind": "line", "sub": "Many of the kingdom's knights were away in the north, besieging Harim with Count Philip of Flanders."}, {"t": 19.562, "d": 4.779, "kind": "line", "sub": "Baldwin rode to Ascalon with a few hundred knights and was shut in there."}, {"t": 24.761, "d": 3.925, "kind": "line", "sub": "Saladin left him behind and pushed north toward Ramla."}, {"t": 29.106, "d": 2.112, "kind": "line", "sub": "His men spread out to plunder."}, {"t": 31.638, "d": 10.411, "kind": "line", "sub": "Baldwin slipped out along the coast, joined by the Templars from Gaza, and on 25 November caught the sultan's army strung out near Montgisard."}, {"t": 42.469, "d": 4.544, "kind": "line", "sub": "Bishop Albert of Bethlehem carried the True Cross before the army."}, {"t": 47.433, "d": 2.581, "kind": "line", "sub": "The charge broke Saladin's host."}, {"t": 50.434, "d": 5.781, "kind": "line", "sub": "The sultan escaped, and his men struggled back across the Sinai, harried by Bedouin."}, {"t": 56.635, "d": 2.624, "kind": "line", "sub": "It was the worst defeat of his career."}]}, "ch:third:third-reynald": {"src": "audio/ch-third-third-reynald.mp3", "dur": 82.698, "cues": [{"t": 0.35, "d": 4.267, "kind": "title", "sub": "1180–1187. The lord of Kerak."}, {"t": 5.517, "d": 5.227, "kind": "line", "sub": "Reynald of Châtillon had spent sixteen years as a prisoner in Aleppo."}, {"t": 11.163, "d": 11.776, "kind": "line", "sub": "Freed in 1176, he married the heiress of Oultrejordain and became lord of Kerak and Montréal, the castles that watched the road between Egypt and Syria."}, {"t": 23.359, "d": 2.944, "kind": "line", "sub": "He raided caravans in time of truce."}, {"t": 26.723, "d": 8.171, "kind": "line", "sub": "In the winter of 1182–83 he had ships carried in pieces across the desert to the Red Sea."}, {"t": 35.314, "d": 7.68, "kind": "line", "sub": "His men raided its coasts, toward the holy cities of Mecca and Medina, until Saladin's fleet hunted them down."}, {"t": 43.414, "d": 9.749, "kind": "line", "sub": "In November 1183 Saladin besieged Kerak during the wedding of Reynald's stepson Humphrey to the king's half-sister Isabella."}, {"t": 53.583, "d": 9.92, "kind": "line", "sub": "Ernoul tells how the bride's mother sent dishes from the feast out to Saladin, and he asked which tower the couple slept in so his engines would spare it."}, {"t": 63.923, "d": 4.736, "kind": "line", "sub": "The leper king, carried in a litter, led the army that relieved the castle."}, {"t": 69.079, "d": 8.021, "kind": "line", "sub": "Around the turn of 1187 Reynald seized a rich caravan in time of truce and refused to give it back."}, {"t": 77.521, "d": 4.757, "kind": "line", "sub": "Saladin swore that if he ever took Reynald, he would kill him himself."}]}, "ch:third:third-succession": {"src": "audio/ch-third-third-succession.mp3", "dur": 74.67, "cues": [{"t": 0.35, "d": 5.269, "kind": "title", "sub": "1185 – May 1187. A kingdom divided."}, {"t": 6.519, "d": 5.461, "kind": "line", "sub": "Baldwin IV died in the spring of 1185, aged twenty-three."}, {"t": 12.401, "d": 6.784, "kind": "line", "sub": "His nephew, the child Baldwin V, followed him with Raymond III of Tripoli as regent."}, {"t": 19.605, "d": 4.267, "kind": "line", "sub": "The boy died at Acre in the summer of 1186."}, {"t": 24.291, "d": 8.512, "kind": "line", "sub": "Sibylla, the dead king's sister, was crowned in the Holy Sepulchre and then placed the crown on her husband, Guy of Lusignan."}, {"t": 33.223, "d": 5.909, "kind": "line", "sub": "Raymond and the Ibelins had wanted Isabella's husband, Humphrey of Toron, as king."}, {"t": 39.553, "d": 4.075, "kind": "line", "sub": "Humphrey would not be a rival king and did homage to Guy."}, {"t": 44.047, "d": 3.797, "kind": "line", "sub": "Raymond refused, and made his own truce with Saladin."}, {"t": 48.265, "d": 11.819, "kind": "line", "sub": "On 1 May 1187 a Muslim force crossing Galilee with Raymond's leave met a small company of Templars and Hospitallers at the Springs of Cresson."}, {"t": 60.503, "d": 2.752, "kind": "line", "sub": "The Master of the Hospital was killed."}, {"t": 63.675, "d": 4.715, "kind": "line", "sub": "Gerard of Ridefort, Master of the Temple, escaped with a few men."}, {"t": 68.81, "d": 5.44, "kind": "line", "sub": "Shaken, Raymond made peace with the king, and the kingdom called out every man it had."}]}, "ch:third:third-hattin": {"src": "audio/ch-third-third-hattin.mp3", "dur": 76.698, "cues": [{"t": 0.35, "d": 5.483, "kind": "title", "sub": "3–4 July 1187. The Horns of Hattin."}, {"t": 6.733, "d": 9.813, "kind": "line", "sub": "By the end of June the kingdom had gathered about 1,200 knights and many thousands of foot soldiers at the springs of Sephoria."}, {"t": 16.966, "d": 4.245, "kind": "line", "sub": "Saladin crossed the Jordan and stormed the town of Tiberias."}, {"t": 21.631, "d": 3.52, "kind": "line", "sub": "Raymond's wife Eschiva held out in its citadel."}, {"t": 25.571, "d": 5.824, "kind": "line", "sub": "Raymond advised the king to stay by the water, even if it cost him Tiberias."}, {"t": 31.815, "d": 2.901, "kind": "line", "sub": "Gerard of Ridefort urged him to march."}, {"t": 35.137, "d": 4.203, "kind": "line", "sub": "On 3 July the army set out across the dry hills."}, {"t": 39.759, "d": 3.179, "kind": "line", "sub": "Harassed all day, it camped without water."}, {"t": 43.358, "d": 3.029, "kind": "line", "sub": "At dawn the Muslims set the brush alight."}, {"t": 46.807, "d": 5.227, "kind": "line", "sub": "On 4 July the foot soldiers broke and climbed the Horns of Hattin."}, {"t": 52.454, "d": 3.157, "kind": "line", "sub": "Raymond cut his way out, and so did Balian."}, {"t": 56.031, "d": 4.8, "kind": "line", "sub": "The knights fought around the king's tent and the True Cross until both fell."}, {"t": 61.251, "d": 4.032, "kind": "line", "sub": "Saladin spared Guy, but killed Reynald with his own hand."}, {"t": 65.703, "d": 5.269, "kind": "line", "sub": "He had the captured Templars and Hospitallers, about two hundred of them, put to death."}, {"t": 71.393, "d": 4.885, "kind": "line", "sub": "The relic of the True Cross was carried to Damascus and never recovered."}]}, "ch:third:third-jerusalem": {"src": "audio/ch-third-third-jerusalem.mp3", "dur": 93.459, "cues": [{"t": 0.35, "d": 6.741, "kind": "title", "sub": "20 September – 2 October 1187. Jerusalem surrenders."}, {"t": 7.991, "d": 3.435, "kind": "line", "sub": "After Hattin the kingdom fell city by city."}, {"t": 11.846, "d": 6.123, "kind": "line", "sub": "Acre opened its gates within days, and Sidon, Beirut, Jaffa and Ascalon followed."}, {"t": 18.389, "d": 6.741, "kind": "line", "sub": "Only Tyre held out, saved by the arrival of Conrad of Montferrat on 14 July."}, {"t": 25.55, "d": 3.136, "kind": "line", "sub": "Balian of Ibelin had escaped to Tyre."}, {"t": 29.106, "d": 7.808, "kind": "line", "sub": "He asked Saladin for safe conduct to fetch his wife and children from Jerusalem, and swore to stay only one night."}, {"t": 37.334, "d": 3.008, "kind": "line", "sub": "In the city the people begged him to lead them."}, {"t": 40.762, "d": 6.357, "kind": "line", "sub": "Ernoul says Saladin released him from his oath and sent his family to Tripoli under escort."}, {"t": 47.539, "d": 5.376, "kind": "line", "sub": "Balian had almost no knights, so he knighted noble boys and some burgesses."}, {"t": 53.335, "d": 5.845, "kind": "line", "sub": "Saladin attacked from 20 September, and his miners broke into the north wall."}, {"t": 59.601, "d": 6.848, "kind": "line", "sub": "Balian then threatened to kill the Muslim prisoners, wreck the holy places and fight to the last man."}, {"t": 66.869, "d": 2.411, "kind": "line", "sub": "Saladin agreed to terms."}, {"t": 69.699, "d": 3.307, "kind": "line", "sub": "On 2 October the city surrendered."}, {"t": 73.426, "d": 6.784, "kind": "line", "sub": "Each Christian could go free for a ransom: ten dinars for a man, five for a woman, one for a child."}, {"t": 80.63, "d": 8.533, "kind": "line", "sub": "Thousands of the poor could not pay and were led away as slaves, though Saladin and his brother al-Adil freed many without payment."}, {"t": 89.583, "d": 3.456, "kind": "line", "sub": "The cross was taken down from the Dome of the Rock."}]}, "ch:third:third-audita": {"src": "audio/ch-third-third-audita.mp3", "dur": 77.646, "cues": [{"t": 0.35, "d": 5.867, "kind": "title", "sub": "October 1187 – January 1188. Audita tremendi."}, {"t": 7.117, "d": 5.248, "kind": "line", "sub": "The news reached the papal court at Ferrara in October 1187."}, {"t": 12.785, "d": 4.245, "kind": "line", "sub": "Pope Urban III died there that month, it was said of grief."}, {"t": 17.45, "d": 6.592, "kind": "line", "sub": "His successor, Gregory VIII, issued the bull Audita tremendi on 29 October."}, {"t": 24.462, "d": 6.72, "kind": "line", "sub": "It called the loss a judgment on the sins of Christians and summoned them to penance and to the cross."}, {"t": 31.602, "d": 9.216, "kind": "line", "sub": "Richard, Count of Poitou and heir of Henry II, took the cross at Tours in November, the first prince north of the Alps to do so."}, {"t": 41.238, "d": 8.299, "kind": "line", "sub": "In January 1188 Henry and Philip II of France, at war over their borders, met at the elm of Gisors."}, {"t": 49.957, "d": 5.013, "kind": "line", "sub": "Archbishop Joscius of Tyre preached to them, and both kings took the cross."}, {"t": 55.39, "d": 9.792, "kind": "line", "sub": "To pay for the expedition both kings levied the Saladin tithe: a tenth of a year's income and movable goods from everyone who did not go."}, {"t": 65.952, "d": 10.944, "kind": "quote", "sub": "Hearing of the severity of the awful judgment which the hand of God has dealt upon the land of Jerusalem, we and our brothers were thrown into such horror and grief that we hardly knew what to do. (abridged)", "source": "Pope Gregory VIII, Audita tremendi, 29 October 1187"}]}, "ch:third:third-guy-acre": {"src": "audio/ch-third-third-guy-acre.mp3", "dur": 62.978, "cues": [{"t": 0.35, "d": 6.016, "kind": "title", "sub": "July 1188 – October 1189. Guy marches on Acre."}, {"t": 7.266, "d": 2.944, "kind": "line", "sub": "Conrad held Tyre through a winter siege."}, {"t": 10.63, "d": 8.768, "kind": "line", "sub": "On 30 December 1187 his galleys destroyed Saladin's squadron off the harbour, and the sultan withdrew."}, {"t": 19.818, "d": 7.723, "kind": "line", "sub": "Saladin released Guy in 1188 after he swore to leave the kingdom, and the clergy freed him from the oath."}, {"t": 27.961, "d": 4.843, "kind": "line", "sub": "When he came to Tyre, Conrad shut the gates and would not accept him as king."}, {"t": 33.223, "d": 8.363, "kind": "line", "sub": "In late August 1189 Guy marched south with a small army, with Pisan ships keeping pace along the coast."}, {"t": 42.006, "d": 8.32, "kind": "line", "sub": "On 28 August he camped on the hill of Toron outside Acre and laid siege to a city stronger than his army."}, {"t": 50.746, "d": 4.907, "kind": "line", "sub": "Fleets of Danes, Frisians, Flemings and Englishmen began to arrive."}, {"t": 56.073, "d": 6.485, "kind": "line", "sub": "On 4 October an attack on Saladin's camp failed, and Gerard of Ridefort was killed."}]}, "ch:third:third-barbarossa": {"src": "audio/ch-third-third-barbarossa.mp3", "dur": 66.05, "cues": [{"t": 0.35, "d": 5.419, "kind": "title", "sub": "May 1189 – May 1190. Barbarossa marches east."}, {"t": 6.669, "d": 5.035, "kind": "line", "sub": "Frederick Barbarossa had marched on the Second Crusade as a young man."}, {"t": 12.123, "d": 12.203, "kind": "line", "sub": "Now in his late sixties, he took the cross at Mainz in March 1188 and left Regensburg on 11 May 1189 with a large, well-ordered army."}, {"t": 24.746, "d": 3.179, "kind": "line", "sub": "King Béla III of Hungary welcomed him."}, {"t": 28.345, "d": 2.667, "kind": "line", "sub": "In Byzantine lands it went worse."}, {"t": 31.431, "d": 6.144, "kind": "line", "sub": "Emperor Isaac II Angelos, who had come to terms with Saladin, held up the march."}, {"t": 37.995, "d": 12.971, "kind": "line", "sub": "Frederick occupied Philippopolis, wintered at Adrianople and threatened Constantinople until Isaac gave way and provided ships to cross the Dardanelles in March 1190."}, {"t": 51.386, "d": 4.864, "kind": "line", "sub": "In Anatolia the Turks of Rûm harried the army through barren country."}, {"t": 56.67, "d": 8.96, "kind": "line", "sub": "On 18 May 1190 the Germans stormed Iconium, the sultan's capital, and won supplies and safe passage."}]}, "ch:third:third-saleph": {"src": "audio/ch-third-third-saleph.mp3", "dur": 50.399, "cues": [{"t": 0.35, "d": 4.096, "kind": "title", "sub": "10 June 1190. Death in the Saleph."}, {"t": 5.346, "d": 4.053, "kind": "line", "sub": "The army crossed the Taurus mountains into Armenian Cilicia."}, {"t": 9.819, "d": 5.696, "kind": "line", "sub": "On 10 June 1190 Frederick reached the river Saleph near Seleucia."}, {"t": 15.935, "d": 5.269, "kind": "line", "sub": "He went into the water, to bathe or to cross, and was swept away and drowned."}, {"t": 21.625, "d": 1.707, "kind": "line", "sub": "The army fell apart."}, {"t": 23.751, "d": 1.472, "kind": "line", "sub": "Many went home."}, {"t": 25.643, "d": 5.931, "kind": "line", "sub": "Frederick's son, Duke Frederick of Swabia, led the rest to Antioch, where sickness struck them."}, {"t": 31.994, "d": 3.115, "kind": "line", "sub": "The emperor's flesh was buried at Antioch."}, {"t": 35.529, "d": 4.267, "kind": "line", "sub": "His bones were carried on toward Jerusalem but never reached it."}, {"t": 40.215, "d": 6.208, "kind": "line", "sub": "A much smaller German force reached Acre with Duke Frederick in October 1190."}, {"t": 46.843, "d": 3.136, "kind": "line", "sub": "He died in the camp the following January."}]}, "ch:third:third-vezelay": {"src": "audio/ch-third-third-vezelay.mp3", "dur": 66.386, "cues": [{"t": 0.35, "d": 4.203, "kind": "title", "sub": "4 July 1190. The kings set out."}, {"t": 5.453, "d": 5.525, "kind": "line", "sub": "Henry II died in July 1189, at war with his own son."}, {"t": 11.398, "d": 5.824, "kind": "line", "sub": "Richard was crowned King of England in September and spent the winter raising money."}, {"t": 17.642, "d": 3.115, "kind": "line", "sub": "He sold offices, lands and lordships."}, {"t": 21.177, "d": 5.227, "kind": "line", "sub": "Richard of Devizes has him say he would sell London if he could find a buyer."}, {"t": 26.823, "d": 4.011, "kind": "line", "sub": "Crusading zeal also turned on the Jews of England."}, {"t": 31.254, "d": 9.237, "kind": "line", "sub": "Riots broke out after the coronation, and in March 1190 the Jews of York died in the castle there, many by their own hands."}, {"t": 40.911, "d": 3.051, "kind": "line", "sub": "William of Newburgh condemned the killers."}, {"t": 44.382, "d": 5.376, "kind": "line", "sub": "Philip and Richard met at Vézelay on 4 July 1190."}, {"t": 50.178, "d": 2.965, "kind": "line", "sub": "They had sworn to share their conquests equally."}, {"t": 53.563, "d": 3.392, "kind": "line", "sub": "Together they marched to Lyon, and there they parted."}, {"t": 57.375, "d": 2.603, "kind": "line", "sub": "Philip went to Genoa to take ship."}, {"t": 60.398, "d": 5.568, "kind": "line", "sub": "Richard went to Marseille to meet his fleet, which had sailed from England around Spain."}]}, "ch:third:third-messina": {"src": "audio/ch-third-third-messina.mp3", "dur": 79.311, "cues": [{"t": 0.35, "d": 5.611, "kind": "title", "sub": "September 1190 – April 1191. Winter in Sicily."}, {"t": 6.861, "d": 6.379, "kind": "line", "sub": "Philip reached Messina on 16 September 1190 and Richard a week later."}, {"t": 13.659, "d": 2.155, "kind": "line", "sub": "Sicily was in turmoil."}, {"t": 16.234, "d": 11.051, "kind": "line", "sub": "King William II, husband of Richard's sister Joan, had died in November 1189, and the new king, Tancred, was holding Joan and her dowry."}, {"t": 27.705, "d": 4.395, "kind": "line", "sub": "Quarrels between the crusaders and the townsmen turned into fighting."}, {"t": 32.519, "d": 7.317, "kind": "line", "sub": "On 4 October Richard's men stormed Messina and raised his banners on its walls, to Philip's anger."}, {"t": 40.257, "d": 5.227, "kind": "line", "sub": "Tancred made peace, released Joan and paid Richard a large sum in gold."}, {"t": 45.903, "d": 3.733, "kind": "line", "sub": "Richard had long been betrothed to Philip's sister Alice."}, {"t": 50.057, "d": 3.733, "kind": "line", "sub": "Now he refused her, and Philip released him for a payment."}, {"t": 54.21, "d": 6.208, "kind": "line", "sub": "Richard's mother, Eleanor of Aquitaine, arrived with his new bride, Berengaria of Navarre."}, {"t": 60.838, "d": 4.096, "kind": "line", "sub": "Philip sailed on 30 March 1191."}, {"t": 65.354, "d": 4.693, "kind": "line", "sub": "Richard followed on 10 April with more than 200 ships."}, {"t": 70.817, "d": 7.744, "kind": "quote", "sub": "He had the valour of Hector, the magnanimity of Achilles; he was not inferior to Alexander, nor less than Roland in valour. (abridged)", "source": "Itinerarium Peregrinorum et Gesta Regis Ricardi, book 2, on Richard"}]}, "ch:third:third-cyprus": {"src": "audio/ch-third-third-cyprus.mp3", "dur": 65.667, "cues": [{"t": 0.35, "d": 3.712, "kind": "title", "sub": "May 1191. The conquest of Cyprus."}, {"t": 4.962, "d": 3.221, "kind": "line", "sub": "Philip reached Acre on 20 April."}, {"t": 8.603, "d": 3.691, "kind": "line", "sub": "Richard's fleet was scattered by a storm after Crete."}, {"t": 12.714, "d": 10.603, "kind": "line", "sub": "Some ships were wrecked on Cyprus, and its ruler, Isaac Komnenos, a Byzantine noble who had made himself emperor there, seized the survivors and their goods."}, {"t": 23.737, "d": 5.227, "kind": "line", "sub": "The ship carrying Joan and Berengaria lay off Limassol and would not land."}, {"t": 29.383, "d": 6.187, "kind": "line", "sub": "Richard arrived on 6 May, stormed ashore at Limassol and routed Isaac's army."}, {"t": 35.99, "d": 5.696, "kind": "line", "sub": "On 12 May he married Berengaria there, and she was crowned Queen of England."}, {"t": 42.106, "d": 4.843, "kind": "line", "sub": "King Guy and other lords sailed over from Acre to seek his support."}, {"t": 47.369, "d": 2.347, "kind": "line", "sub": "Isaac submitted, then fled."}, {"t": 50.135, "d": 3.093, "kind": "line", "sub": "Richard's forces took the island's castles."}, {"t": 53.649, "d": 7.467, "kind": "line", "sub": "When Isaac finally surrendered, he asked not to be put in irons, so Richard had him bound in chains of silver."}, {"t": 61.535, "d": 3.712, "kind": "line", "sub": "Cyprus stayed in Latin hands for three centuries."}]}, "ch:third:third-acre": {"src": "audio/ch-third-third-acre.mp3", "dur": 96.659, "cues": [{"t": 0.35, "d": 5.419, "kind": "title", "sub": "August 1189 – August 1191. The siege of Acre."}, {"t": 6.669, "d": 3.136, "kind": "line", "sub": "The siege of Acre drew in all of Christendom."}, {"t": 10.225, "d": 7.851, "kind": "line", "sub": "Saladin camped on the hills behind the besiegers, so they were besieged in turn, and dug ditches facing both ways."}, {"t": 18.495, "d": 6.421, "kind": "line", "sub": "In the winter of 1190–91 famine and disease killed thousands."}, {"t": 25.337, "d": 7.253, "kind": "line", "sub": "Queen Sibylla and her daughters died in the camp, and Isabella, now heiress, married Conrad of Montferrat."}, {"t": 33.01, "d": 4.8, "kind": "line", "sub": "Philip arrived in April 1191 and Richard in June."}, {"t": 38.23, "d": 3.221, "kind": "line", "sub": "Their engines pounded the walls day and night."}, {"t": 41.871, "d": 6.549, "kind": "line", "sub": "The Itinerarium names Philip's great trebuchet Bad Neighbour, and the garrison's answer Bad Kinsman."}, {"t": 48.841, "d": 6.464, "kind": "line", "sub": "Another, paid for from common funds, was called God's Own Sling, and a priest preached beside it."}, {"t": 55.725, "d": 3.648, "kind": "line", "sub": "Miners and assaults brought down the Accursed Tower."}, {"t": 59.793, "d": 4.693, "kind": "line", "sub": "On 12 July 1191 the garrison surrendered."}, {"t": 64.906, "d": 6.677, "kind": "line", "sub": "Saladin was to pay 200,000 dinars, free Christian captives and return the True Cross."}, {"t": 72.003, "d": 4.48, "kind": "line", "sub": "Leopold of Austria, slighted by the kings, went home angry."}, {"t": 76.903, "d": 3.413, "kind": "line", "sub": "Philip, ill, sailed for France at the end of July."}, {"t": 80.737, "d": 1.941, "kind": "line", "sub": "The payments were delayed."}, {"t": 83.098, "d": 13.141, "kind": "line", "sub": "On 20 August Richard had about 2,700 prisoners of the garrison led out and killed in sight of Saladin's army, as the Itinerarium and Ambroise record."}]}, "ch:third:third-arsuf": {"src": "audio/ch-third-third-arsuf.mp3", "dur": 73.981, "cues": [{"t": 0.35, "d": 3.883, "kind": "title", "sub": "7 September 1191. Arsuf."}, {"t": 5.133, "d": 3.712, "kind": "line", "sub": "Richard's goal was Jaffa, the port for Jerusalem."}, {"t": 9.265, "d": 7.019, "kind": "line", "sub": "He led the army south along the coast road in short stages, with the fleet alongside carrying food."}, {"t": 16.703, "d": 7.787, "kind": "line", "sub": "Foot soldiers on the landward side shielded the horses, and crossbowmen kept the Turkish horse archers at a distance."}, {"t": 24.91, "d": 7.019, "kind": "line", "sub": "The Itinerarium describes foot soldiers marching on with arrows stuck all over their padded coats."}, {"t": 32.349, "d": 5.781, "kind": "line", "sub": "On 7 September, north of Arsuf, Saladin threw his whole army at the column."}, {"t": 38.55, "d": 1.941, "kind": "line", "sub": "Richard held his knights back."}, {"t": 40.911, "d": 4.651, "kind": "line", "sub": "The Hospitallers at the rear were losing horses and begged to charge."}, {"t": 45.982, "d": 5.888, "kind": "line", "sub": "At last the Marshal of the Hospital and Baldwin Carew broke ranks, and the rear followed them."}, {"t": 52.29, "d": 5.12, "kind": "line", "sub": "Richard turned the breakout into a full charge, and Saladin's army broke."}, {"t": 57.83, "d": 6.677, "kind": "line", "sub": "When it rallied, Richard charged again, then held his men together instead of chasing into the forest."}, {"t": 64.927, "d": 5.141, "kind": "line", "sub": "James of Avesnes, a hero of the siege of Acre, died on the field."}, {"t": 70.489, "d": 3.072, "kind": "line", "sub": "Three days later the army reached Jaffa."}]}, "ch:third:third-beit-nuba": {"src": "audio/ch-third-third-beit-nuba.mp3", "dur": 67.579, "cues": [{"t": 0.35, "d": 6.485, "kind": "title", "sub": "November 1191 – January 1192. Within reach of Jerusalem."}, {"t": 7.735, "d": 6.464, "kind": "line", "sub": "Through the autumn Richard rebuilt the castles on the Jaffa road while envoys went back and forth."}, {"t": 14.619, "d": 7.808, "kind": "line", "sub": "He even proposed that his sister Joan marry Saladin's brother al-Adil, and that the two rule Jerusalem together."}, {"t": 22.847, "d": 2.752, "kind": "line", "sub": "Joan refused to marry a Muslim."}, {"t": 26.019, "d": 7.787, "kind": "line", "sub": "Around the new year the army pushed inland through rain and hail to Beit Nuba, about twelve miles from Jerusalem."}, {"t": 34.226, "d": 3.328, "kind": "line", "sub": "Food rotted and horses died in the mud."}, {"t": 37.974, "d": 9.387, "kind": "line", "sub": "The Templars, the Hospitallers and the barons of the land warned that even if the city fell, it could not be held once the pilgrims went home."}, {"t": 47.781, "d": 5.44, "kind": "line", "sub": "On 13 January 1192 Richard ordered the retreat."}, {"t": 53.641, "d": 5.611, "kind": "line", "sub": "The ordinary pilgrims, who had longed to see the Holy Sepulchre, turned back in grief."}, {"t": 59.671, "d": 7.488, "kind": "line", "sub": "Richard marched to Ascalon instead and spent the spring rebuilding its walls to cut Saladin's road to Egypt."}]}, "ch:third:third-second-approach": {"src": "audio/ch-third-third-second-approach.mp3", "dur": 79.275, "cues": [{"t": 0.35, "d": 5.355, "kind": "title", "sub": "April – July 1192. A king murdered, a second retreat."}, {"t": 6.605, "d": 4.395, "kind": "line", "sub": "News came from England that Richard's brother John was plotting."}, {"t": 11.419, "d": 3.541, "kind": "line", "sub": "Richard had to settle the crown before he went home."}, {"t": 15.381, "d": 7.147, "kind": "line", "sub": "In April 1192 the barons chose Conrad of Montferrat as king, and Richard accepted."}, {"t": 22.947, "d": 2.517, "kind": "line", "sub": "Guy was given Cyprus instead."}, {"t": 25.885, "d": 11.115, "kind": "line", "sub": "On 28 April, before he could be crowned, Conrad was stabbed to death in a street of Tyre by two Assassins who had lived in the city disguised as monks."}, {"t": 37.419, "d": 3.2, "kind": "line", "sub": "Some blamed Richard, but nothing links him to it."}, {"t": 41.039, "d": 5.184, "kind": "line", "sub": "Eight days later the widowed Isabella married Count Henry of Champagne."}, {"t": 46.643, "d": 6.955, "kind": "line", "sub": "In June the army marched to Beit Nuba again, and Richard's men captured a great caravan from Egypt."}, {"t": 54.018, "d": 12.288, "kind": "line", "sub": "A council of twenty, of Templars, Hospitallers, French lords and barons of the land, advised against a siege in the summer heat with the cisterns around Jerusalem destroyed."}, {"t": 66.726, "d": 3.627, "kind": "line", "sub": "In early July the army turned back a second time."}, {"t": 71.123, "d": 7.403, "kind": "quote", "sub": "Fair Lord God, I pray Thee suffer me not to see Thy Holy City, since I cannot deliver it from the hands of Thine enemies.", "source": "Jean de Joinville, Life of Saint Louis, retelling a story of Richard more than a century later"}]}, "ch:third:third-jaffa": {"src": "audio/ch-third-third-jaffa.mp3", "dur": 75.275, "cues": [{"t": 0.35, "d": 5.483, "kind": "title", "sub": "28 July – 5 August 1192. Jaffa."}, {"t": 6.733, "d": 3.883, "kind": "line", "sub": "Richard had gone north to Acre, planning to attack Beirut."}, {"t": 11.035, "d": 2.603, "kind": "line", "sub": "Saladin struck at Jaffa at once."}, {"t": 14.058, "d": 4.032, "kind": "line", "sub": "His miners broke the walls and his troops poured into the town."}, {"t": 18.51, "d": 4.928, "kind": "line", "sub": "The garrison, holding the citadel, agreed to surrender if no help came."}, {"t": 23.858, "d": 2.795, "kind": "line", "sub": "Richard sailed south with a few galleys."}, {"t": 27.073, "d": 9.643, "kind": "line", "sub": "On 1 August, seeing the citadel still held, he leapt into the sea, waded ashore with his men and drove Saladin's troops out of the town."}, {"t": 37.135, "d": 6.421, "kind": "line", "sub": "At dawn on 5 August Saladin's cavalry attacked the small camp outside the walls."}, {"t": 43.977, "d": 5.227, "kind": "line", "sub": "Richard had a few dozen knights, few of them mounted, and some two thousand foot."}, {"t": 49.623, "d": 3.904, "kind": "line", "sub": "The knights knelt in a line with shields and lances braced."}, {"t": 53.947, "d": 5.013, "kind": "line", "sub": "Behind them the crossbowmen worked in pairs, one loading while the other shot."}, {"t": 59.381, "d": 3.499, "kind": "line", "sub": "Charge after charge turned away before the line."}, {"t": 63.299, "d": 5.12, "kind": "line", "sub": "Late in the day Richard mounted and charged, and Saladin's army withdrew."}, {"t": 68.839, "d": 6.016, "kind": "line", "sub": "The Christian chroniclers tell that during the fighting al-Adil sent Richard two fine horses."}]}, "ch:third:third-treaty": {"src": "audio/ch-third-third-treaty.mp3", "dur": 63.847, "cues": [{"t": 0.35, "d": 4.757, "kind": "title", "sub": "2 September 1192. The Treaty of Jaffa."}, {"t": 6.007, "d": 1.728, "kind": "line", "sub": "Both sides were spent."}, {"t": 8.155, "d": 4.288, "kind": "line", "sub": "Richard fell sick, and Saladin's emirs were tired of the war."}, {"t": 12.863, "d": 6.357, "kind": "line", "sub": "On 2 September 1192 they agreed a truce of three years and eight months."}, {"t": 19.641, "d": 3.563, "kind": "line", "sub": "The Christians kept the coast from Tyre to Jaffa."}, {"t": 23.623, "d": 3.925, "kind": "line", "sub": "Ascalon, rebuilt at such cost, was to be pulled down."}, {"t": 27.969, "d": 3.712, "kind": "line", "sub": "Christian pilgrims could visit Jerusalem freely."}, {"t": 32.101, "d": 5.291, "kind": "line", "sub": "Many crusaders went up to Jerusalem in parties under safe conduct."}, {"t": 37.811, "d": 1.835, "kind": "line", "sub": "Richard would not go."}, {"t": 40.066, "d": 10.987, "kind": "line", "sub": "Hubert Walter, Bishop of Salisbury, met Saladin and asked that two Latin priests and two deacons might serve at the Holy Sepulchre, at Bethlehem and at Nazareth."}, {"t": 51.473, "d": 1.749, "kind": "line", "sub": "Saladin granted it."}, {"t": 53.642, "d": 3.52, "kind": "line", "sub": "On 9 October Richard sailed from Acre."}, {"t": 57.582, "d": 5.845, "kind": "line", "sub": "The Kingdom of Jerusalem had survived, now as a strip of coast ruled from Acre."}]}, "ch:third:third-epilogue": {"src": "audio/ch-third-third-epilogue.mp3", "dur": 69.685, "cues": [{"t": 0.35, "d": 3.989, "kind": "title", "sub": "1192 and after. The long road home."}, {"t": 5.239, "d": 3.84, "kind": "line", "sub": "Richard's ship was wrecked at the head of the Adriatic."}, {"t": 9.499, "d": 10.795, "kind": "line", "sub": "Travelling in disguise, he was recognised near Vienna in December 1192 and seized by Duke Leopold of Austria, whom he had offended at Acre."}, {"t": 20.714, "d": 4.523, "kind": "line", "sub": "Leopold handed him to Emperor Henry VI, Barbarossa's son."}, {"t": 25.657, "d": 7.701, "kind": "line", "sub": "In prison Richard wrote a song, Ja nus hons pris, complaining that his men had left him captive for two winters."}, {"t": 33.778, "d": 10.027, "kind": "line", "sub": "He was freed in February 1194 for a ransom of 150,000 marks, raised by heavy taxes across his lands."}, {"t": 44.225, "d": 6.379, "kind": "line", "sub": "He never returned to the East and died of a crossbow wound at Châlus in 1199."}, {"t": 51.023, "d": 5.12, "kind": "line", "sub": "Saladin had died at Damascus on 4 March 1193."}, {"t": 56.563, "d": 3.584, "kind": "line", "sub": "The Third Crusade did not recover Jerusalem."}, {"t": 60.567, "d": 1.856, "kind": "line", "sub": "It did save the kingdom."}, {"t": 62.843, "d": 6.421, "kind": "line", "sub": "From Acre, the Latin East lasted another century, until Acre fell in 1291."}]}, "sc:third:montgisard": {"src": "audio/sc-third-montgisard.mp3", "dur": 58.314, "cues": [{"t": 0.35, "d": 2.347, "kind": "title", "sub": "The battle of Montgisard."}, {"t": 3.597, "d": 11.307, "kind": "phase", "sub": "25 November 1177. Saladin has left the king shut up in Ascalon and marched north. His raiders spread out to plunder around Ramla.", "phase": 0}, {"t": 15.603, "d": 8.448, "kind": "phase", "sub": "Baldwin, sixteen and already sick, slips out of Ascalon with a few hundred knights. The Templars of Gaza ride to join him.", "phase": 1}, {"t": 24.751, "d": 9.728, "kind": "phase", "sub": "Bishop Albert of Bethlehem holds up the True Cross before the army. Saladin's men are caught strung out across a ravine and try to form a line.", "phase": 2}, {"t": 35.179, "d": 7.019, "kind": "phase", "sub": "The knights charge into the disordered host. Reynald and the Templars ride straight at the sultan's guard.", "phase": 3}, {"t": 42.898, "d": 6.741, "kind": "phase", "sub": "The guard is cut down around Saladin. The sultan escapes south, and his whole army breaks and runs.", "phase": 4}, {"t": 50.339, "d": 7.275, "kind": "phase", "sub": "Few of the invaders reached Egypt. Rain and Bedouin raiders harried them all the way across the Sinai.", "phase": 5}]}, "sc:third:hattin": {"src": "audio/sc-third-hattin.mp3", "dur": 77.105, "cues": [{"t": 0.35, "d": 1.92, "kind": "title", "sub": "The battle of Hattin."}, {"t": 3.17, "d": 12.053, "kind": "phase", "sub": "3 July 1187. The army leaves the springs of Sephoria to relieve Tiberias. Raymond leads the vanguard, the Templars and Balian the rearguard.", "phase": 0}, {"t": 15.923, "d": 9.963, "kind": "phase", "sub": "Saladin's horsemen close in on every side. The rear is pressed so hard that the army halts for the night on the dry plateau, with no water.", "phase": 1}, {"t": 26.586, "d": 9.003, "kind": "phase", "sub": "All night the army goes without water. At dawn the Muslims set the dry brush alight, and the smoke blows into the Christian ranks.", "phase": 2}, {"t": 36.289, "d": 9.195, "kind": "phase", "sub": "4 July. The foot soldiers break away and climb the Horns of Hattin. They will not come down, though the king and the bishops beg them.", "phase": 3}, {"t": 46.183, "d": 10.091, "kind": "phase", "sub": "Raymond charges the enemy line. Taqi al-Din's men open their ranks to let him through, then close again. Later Balian too cuts his way out.", "phase": 4}, {"t": 56.974, "d": 8.021, "kind": "phase", "sub": "The king pitches his tent near the Horns. His knights charge down at Saladin and are driven back. The True Cross is taken.", "phase": 5}, {"t": 65.695, "d": 10.709, "kind": "phase", "sub": "The king's tent falls and Guy is captured. Saladin spares him but kills Reynald with his own hand, and has the Templars and Hospitallers put to death.", "phase": 6}]}, "sc:third:acre": {"src": "audio/sc-third-acre.mp3", "dur": 69.066, "cues": [{"t": 0.35, "d": 1.813, "kind": "title", "sub": "The siege of Acre."}, {"t": 3.063, "d": 11.52, "kind": "phase", "sub": "28 August 1189. King Guy, freed by Saladin, arrives with a small army and camps on the hill of Toron. Christian ships close the sea.", "phase": 0}, {"t": 15.283, "d": 9.792, "kind": "phase", "sub": "Saladin comes up and surrounds the besiegers, who are now besieged themselves. Through two winters of hunger and disease they fight on both fronts.", "phase": 1}, {"t": 25.775, "d": 10.411, "kind": "phase", "sub": "April 1191. Philip of France lands and sets up his great trebuchet, Bad Neighbour. The garrison answers with an engine it calls Bad Kinsman.", "phase": 2}, {"t": 36.886, "d": 10.603, "kind": "phase", "sub": "June 1191. Richard arrives with his fleet. God's Own Sling, paid for from common funds, joins the bombardment of the Accursed Tower.", "phase": 3}, {"t": 48.189, "d": 9.493, "kind": "phase", "sub": "Miners and assaults bring down the walls. Saladin attacks the camp to draw the besiegers off, but the knights and crossbowmen hold the ditches.", "phase": 4}, {"t": 58.382, "d": 9.984, "kind": "phase", "sub": "12 July 1191. The exhausted garrison surrenders. The kings' banners go up over Acre after nearly two years of siege.", "phase": 5}]}, "sc:third:arsuf": {"src": "audio/sc-third-arsuf.mp3", "dur": 60.405, "cues": [{"t": 0.35, "d": 1.984, "kind": "title", "sub": "The battle of Arsuf."}, {"t": 3.234, "d": 11.605, "kind": "phase", "sub": "7 September 1191. Richard's army marches south toward Arsuf in close order. The sea guards its right, and foot soldiers screen the landward side.", "phase": 0}, {"t": 15.539, "d": 8.064, "kind": "phase", "sub": "Saladin's army bursts out of the forest. Horse archers and foot swarm against the column, aiming above all at the rear.", "phase": 1}, {"t": 24.303, "d": 8.533, "kind": "phase", "sub": "The Hospitallers are losing horses under the arrows. Their Master begs leave to charge. Richard tells him to wait for the signal.", "phase": 2}, {"t": 33.537, "d": 6.656, "kind": "phase", "sub": "The Marshal of the Hospital and Baldwin Carew break ranks and charge. The whole rear goes with them.", "phase": 3}, {"t": 40.893, "d": 8.277, "kind": "phase", "sub": "Richard sees the charge cannot be recalled and sends in the whole army. Saladin's men are thrown back toward the forest.", "phase": 4}, {"t": 49.87, "d": 9.835, "kind": "phase", "sub": "Saladin rallies his men at the edge of the wood. Richard charges again, then halts and keeps his army together. That evening it camps at Arsuf.", "phase": 5}]}, "sc:third:jaffa": {"src": "audio/sc-third-jaffa.mp3", "dur": 64.351, "cues": [{"t": 0.35, "d": 2.048, "kind": "title", "sub": "The battle of Jaffa."}, {"t": 3.298, "d": 10.624, "kind": "phase", "sub": "Late July 1192. Saladin storms Jaffa while Richard is at Acre. His troops pour into the town, and the garrison holds out in the citadel.", "phase": 0}, {"t": 14.622, "d": 9.664, "kind": "phase", "sub": "1 August. Richard's galleys sail in. Seeing the citadel still holds, the king leaps into the sea and wades ashore at the head of his men.", "phase": 1}, {"t": 24.986, "d": 8.96, "kind": "phase", "sub": "The small force clears the town. Richard camps outside the walls with a few dozen knights, few with horses, and some two thousand foot.", "phase": 2}, {"t": 34.646, "d": 12.224, "kind": "phase", "sub": "5 August, dawn. Saladin's cavalry attacks. The knights kneel behind their shields with lances braced. Behind them crossbowmen work in pairs, one loading, one shooting.", "phase": 3}, {"t": 47.57, "d": 6.165, "kind": "phase", "sub": "Wave after wave of horsemen rides at the line and turns away before the hedge of lances.", "phase": 4}, {"t": 54.435, "d": 9.216, "kind": "phase", "sub": "Late in the day Richard mounts with a handful of knights and charges. Saladin's army draws off, and Jaffa stays in Christian hands.", "phase": 5}]}, "sc:third:gisors": {"src": "audio/sc-third-gisors.mp3", "dur": 43.645, "cues": [{"t": 0.35, "d": 1.877, "kind": "title", "sub": "The kings take the cross."}, {"t": 3.127, "d": 12.139, "kind": "phase", "sub": "21 January 1188. Henry II and Philip II meet at the great elm between Gisors and Trie, on the border of Normandy, to argue over land.", "phase": 0}, {"t": 15.966, "d": 8.277, "kind": "phase", "sub": "Joscius, Archbishop of Tyre, comes from the East with news of Hattin and the loss of Jerusalem, and preaches the cross.", "phase": 1}, {"t": 24.943, "d": 7.019, "kind": "phase", "sub": "The two kings, long at war, make peace and take the cross together. Count Philip of Flanders follows them.", "phase": 2}, {"t": 32.662, "d": 10.283, "kind": "phase", "sub": "Their men take the cross by nations: red crosses for the French, white for the English, green for the Flemings. Both kings then decree the Saladin tithe.", "phase": 3}]}, "sc:third:vezelay": {"src": "audio/sc-third-vezelay.mp3", "dur": 37.778, "cues": [{"t": 0.35, "d": 2.453, "kind": "title", "sub": "The kings set out from Vézelay."}, {"t": 3.703, "d": 11.349, "kind": "phase", "sub": "4 July 1190, three years to the day after Hattin. The French and English armies gather below Vézelay, where St Bernard preached the Second Crusade.", "phase": 0}, {"t": 15.753, "d": 5.803, "kind": "phase", "sub": "Richard and Philip meet. They have sworn to share equally whatever they win on the journey.", "phase": 1}, {"t": 22.255, "d": 6.016, "kind": "phase", "sub": "The clergy bless the host, and the two kings ride out together at the head of their armies.", "phase": 2}, {"t": 28.971, "d": 8.107, "kind": "phase", "sub": "At Lyon a bridge over the Rhône gives way under the crowds. There the kings part: Philip for Genoa, Richard for Marseille.", "phase": 3}]}, "outro": {"src": "audio/outro.mp3", "dur": 10.534, "cues": [{"t": 0.35, "d": 7.509, "kind": "line", "sub": "The crusader kingdom on the coast would last another hundred years, until Acre fell in 1291."}, {"t": 8.279, "d": 1.835, "kind": "line", "sub": "Here ends the chronicle."}]}};
